draw:
const th = p.angle * Math.PI / 180;
const g = p.gravity, v0 = p.speed;
const range = v0 * v0 * Math.sin(2 * th) / g;
const hMax  = v0 * v0 * Math.pow(Math.sin(th), 2) / (2 * g);
const tFly  = 2 * v0 * Math.sin(th) / g;

const pad = 28;
const maxX = Math.max(range * 1.08, 20);
const maxY = Math.max(hMax * 1.35, 12);
const sx = (W - pad * 2) / maxX, sy = (H - pad * 2) / maxY;
const X = x => pad + x * sx;
const Y = y => H - pad - y * sy;

// ground
ctx.strokeStyle = C.faint;
ctx.beginPath(); ctx.moveTo(0, Y(0)); ctx.lineTo(W, Y(0)); ctx.stroke();

// full path
ctx.strokeStyle = C.rule;
ctx.setLineDash([4, 5]);
ctx.beginPath();
for (let s = 0; s <= tFly; s += tFly / 120) {
  const x = v0 * Math.cos(th) * s, y = v0 * Math.sin(th) * s - 0.5 * g * s * s;
  s === 0 ? ctx.moveTo(X(x), Y(y)) : ctx.lineTo(X(x), Y(y));
}
ctx.stroke();
ctx.setLineDash([]);

// travelled so far
const now = t % (tFly + 0.6);
const cur = Math.min(now, tFly);
ctx.strokeStyle = C.accent;
ctx.lineWidth = 2;
ctx.beginPath();
for (let s = 0; s <= cur; s += tFly / 120) {
  const x = v0 * Math.cos(th) * s, y = v0 * Math.sin(th) * s - 0.5 * g * s * s;
  s === 0 ? ctx.moveTo(X(x), Y(y)) : ctx.lineTo(X(x), Y(y));
}
ctx.stroke();

// projectile and velocity vector
const px = v0 * Math.cos(th) * cur;
const py = Math.max(0, v0 * Math.sin(th) * cur - 0.5 * g * cur * cur);
const vx = v0 * Math.cos(th), vy = v0 * Math.sin(th) - g * cur;
ctx.strokeStyle = C.figure;
ctx.lineWidth = 1.5;
ctx.beginPath();
ctx.moveTo(X(px), Y(py));
ctx.lineTo(X(px) + vx * 1.5, Y(py) - vy * 1.5);
ctx.stroke();

ctx.fillStyle = C.accent;
ctx.beginPath(); ctx.arc(X(px), Y(py), 5, 0, Math.PI * 2); ctx.fill();

out.note = "range " + range.toFixed(1) + " m, peak " + hMax.toFixed(1) + " m, flight " + tFly.toFixed(2) + " s";

const omega = Math.sqrt(p.k / p.mass);
const wallX = 26, eqX = W * 0.34, scale = W * 0.16, midY = H * 0.34;
const x = p.amplitude * Math.cos(omega * t);
const massX = eqX + x * scale;

// wall
ctx.fillStyle = C.faint;
ctx.fillRect(wallX - 6, midY - 38, 6, 76);

// spring
ctx.strokeStyle = C.accent;
ctx.lineWidth = 2;
ctx.beginPath();
ctx.moveTo(wallX, midY);
for (let i = 1; i <= 12; i++) {
  const sxp = wallX + (massX - 16 - wallX) * i / 12;
  const syp = midY + (i % 2 === 0 ? -10 : 10) * (i === 12 ? 0 : 1);
  ctx.lineTo(sxp, syp);
}
ctx.lineTo(massX - 16, midY);
ctx.stroke();

// equilibrium marker
ctx.strokeStyle = C.rule;
ctx.setLineDash([3, 5]);
ctx.beginPath(); ctx.moveTo(eqX, midY - 44); ctx.lineTo(eqX, midY + 44); ctx.stroke();
ctx.setLineDash([]);

// mass
ctx.fillStyle = C.figure;
ctx.beginPath(); ctx.roundRect(massX - 16, midY - 16, 32, 32, 4); ctx.fill();

// x(t) trace
const gy = H * 0.8;
ctx.strokeStyle = C.rule;
ctx.beginPath(); ctx.moveTo(16, gy); ctx.lineTo(W - 16, gy); ctx.stroke();
ctx.strokeStyle = C.figure;
ctx.lineWidth = 1.5;
ctx.beginPath();
for (let i = 0; i < 240; i++) {
  const tt = t - (240 - i) * 0.016;
  const px2 = W - 16 - (240 - i) * 1.3;
  const py2 = gy - p.amplitude * Math.cos(omega * tt) * 26;
  i === 0 ? ctx.moveTo(px2, py2) : ctx.lineTo(px2, py2);
}
ctx.stroke();

out.note = "T = " + (2 * Math.PI / omega).toFixed(2) + " s, omega = " + omega.toFixed(2) + " rad/s";

const T = 8, pad = 26, half = W / 2;
const xs = s => p.v0 * s + 0.5 * p.a * s * s;
const vs = s => p.v0 + p.a * s;

let xLo = 0, xHi = 0, vLo = 0, vHi = 0;
for (let s = 0; s <= T; s += 0.1) {
  xLo = Math.min(xLo, xs(s)); xHi = Math.max(xHi, xs(s));
  vLo = Math.min(vLo, vs(s)); vHi = Math.max(vHi, vs(s));
}
const span = (lo, hi) => (hi - lo === 0 ? 1 : hi - lo);
const Y = (val, lo, hi) => H - pad - (val - lo) / span(lo, hi) * (H - pad * 2);
const X1 = s => pad + s / T * (half - pad * 1.7);
const X2 = s => half + pad + s / T * (half - pad * 1.7);
const now = t % T;

const panels = [
  { f: xs, lo: xLo, hi: xHi, X: X1, color: C.figure, label: "x(t)" },
  { f: vs, lo: vLo, hi: vHi, X: X2, color: C.accent,  label: "v(t)" },
];

for (const q of panels) {
  ctx.strokeStyle = C.rule;
  ctx.lineWidth = 1;
  ctx.beginPath(); ctx.moveTo(q.X(0), pad / 2); ctx.lineTo(q.X(0), H - pad / 2); ctx.stroke();
  const zero = Y(0, q.lo, q.hi);
  ctx.beginPath(); ctx.moveTo(q.X(0), zero); ctx.lineTo(q.X(T), zero); ctx.stroke();

  ctx.strokeStyle = q.color;
  ctx.lineWidth = 2;
  ctx.beginPath();
  for (let s = 0; s <= T; s += 0.05) {
    const cx2 = q.X(s), cy2 = Y(q.f(s), q.lo, q.hi);
    s === 0 ? ctx.moveTo(cx2, cy2) : ctx.lineTo(cx2, cy2);
  }
  ctx.stroke();

  ctx.fillStyle = q.color;
  ctx.beginPath(); ctx.arc(q.X(now), Y(q.f(now), q.lo, q.hi), 4, 0, Math.PI * 2); ctx.fill();
  ctx.font = "11px ui-sans-serif, system-ui, sans-serif";
  ctx.textAlign = "left";
  ctx.fillText(q.label, q.X(0) + 5, pad / 2 + 9);
}

const turn = p.a !== 0 ? -p.v0 / p.a : -1;
out.note = turn > 0 && turn < T ? "v = 0 at t = " + turn.toFixed(1) + " s" : "v never reaches zero here";

const m1 = p.m1, m2 = p.m2, u1 = p.u1, elastic = p.elastic >= 0.5;
const v1f = elastic ? (m1 - m2) / (m1 + m2) * u1 : m1 * u1 / (m1 + m2);
const v2f = elastic ? 2 * m1 / (m1 + m2) * u1 : m1 * u1 / (m1 + m2);
const keLoss = elastic ? 0 : m2 / (m1 + m2) * 100;

const floor = H * 0.72;
const s1 = 20 + m1 * 4, s2 = 20 + m2 * 4;
const scale = 24;
const startGap = W * 0.45;
const cycle = (startGap - s1) / (u1 * scale) + 2.6;
const now = t % cycle;
const tHit = (startGap - s1) / (u1 * scale);

let x1, x2;
if (now < tHit) {
  x1 = 40 + u1 * scale * now;
  x2 = 40 + startGap;
} else {
  const after = now - tHit;
  x1 = 40 + (startGap - s1) + v1f * scale * after;
  x2 = 40 + startGap + v2f * scale * after;
  if (!elastic) x2 = x1 + s1;
}

ctx.strokeStyle = C.faint;
ctx.beginPath(); ctx.moveTo(0, floor); ctx.lineTo(W, floor); ctx.stroke();

const block = (x, size, color, label, vel) => {
  ctx.fillStyle = color;
  ctx.beginPath(); ctx.roundRect(x, floor - size, size, size, 3); ctx.fill();
  ctx.fillStyle = C.paper;
  ctx.font = "11px ui-sans-serif, system-ui, sans-serif";
  ctx.textAlign = "center";
  ctx.fillText(label, x + size / 2, floor - size / 2 + 4);
  if (Math.abs(vel) > 0.05) {
    const cx2 = x + size / 2, y = floor - size - 11;
    ctx.strokeStyle = C.ink;
    ctx.beginPath();
    ctx.moveTo(cx2, y); ctx.lineTo(cx2 + vel * 8, y);
    ctx.lineTo(cx2 + vel * 8 - Math.sign(vel) * 4, y - 3);
    ctx.moveTo(cx2 + vel * 8, y);
    ctx.lineTo(cx2 + vel * 8 - Math.sign(vel) * 4, y + 3);
    ctx.stroke();
  }
};

block(x1, s1, C.figure, "m1", now < tHit ? u1 : v1f);
block(x2, s2, C.accent, "m2", now < tHit ? 0 : v2f);

out.note = "after: v1 = " + v1f.toFixed(2) + ", v2 = " + v2f.toFixed(2) + " m/s, KE lost " + keLoss.toFixed(0) + "%";

var mu0 = 4 * Math.PI * 1e-7;
var I = p.current, a = p.radius / 1000, rp = p.probe / 1000;
var Bsurf = mu0 * I / (2 * Math.PI * a);
var B = rp <= a ? mu0 * I * rp / (2 * Math.PI * a * a) : mu0 * I / (2 * Math.PI * rp);

ctx.font = "12px ui-sans-serif, system-ui, sans-serif";
ctx.textAlign = "left";
ctx.textBaseline = "alphabetic";

// ---- left panel: cross-section ----
var cx = W * 0.24, cy = H * 0.52;
var rmax = a * 3;                       // metres shown across the panel
var pix = Math.min(W * 0.20, H * 0.38) / rmax;   // pixels per metre
var wireR = a * pix;

ctx.strokeStyle = C.rule;
ctx.fillStyle = C.faint;
ctx.beginPath(); ctx.arc(cx, cy, wireR, 0, Math.PI * 2); ctx.fill(); ctx.stroke();

// current-out-of-page dots
ctx.fillStyle = C.figure;
for (var ix = -2; ix <= 2; ix++) {
  for (var iy = -2; iy <= 2; iy++) {
    var dx = ix * wireR * 0.42, dy = iy * wireR * 0.42;
    if (dx * dx + dy * dy < wireR * wireR * 0.75) {
      ctx.beginPath(); ctx.arc(cx + dx, cy + dy, 1.6, 0, Math.PI * 2); ctx.fill();
    }
  }
}

// the Amperian circle
var pr = rp * pix;
ctx.strokeStyle = C.accent;
ctx.setLineDash([4, 4]);
ctx.beginPath(); ctx.arc(cx, cy, pr, 0, Math.PI * 2); ctx.stroke();
ctx.setLineDash([]);

// a marker running round the loop, faster where B is bigger
var speed = 0.7 + 5.0 * (B / (Bsurf + 1e-30));
var ang = (t * speed) % (Math.PI * 2);
ctx.fillStyle = C.accent;
ctx.beginPath(); ctx.arc(cx + pr * Math.cos(ang), cy + pr * Math.sin(ang), 4, 0, Math.PI * 2); ctx.fill();

// B arrow, tangent to the loop at the marker
var tx = -Math.sin(ang), ty = Math.cos(ang);
var hx = cx + pr * Math.cos(ang), hy = cy + pr * Math.sin(ang);
ctx.strokeStyle = C.accent;
ctx.lineWidth = 1.5;
ctx.beginPath();
ctx.moveTo(hx, hy); ctx.lineTo(hx + tx * 18, hy + ty * 18); ctx.stroke();
ctx.lineWidth = 1;

ctx.fillStyle = C.ink;
ctx.fillText("current I out of page", cx - wireR, cy + Math.min(W * 0.20, H * 0.38) + 16);
ctx.fillStyle = C.accent;
ctx.fillText("Amperian loop", cx - wireR, cy - Math.min(W * 0.20, H * 0.38) - 6);

// ---- right panel: B against r ----
var gx0 = W * 0.50, gx1 = W - 14, gy0 = 18, gy1 = H - 30;
ctx.strokeStyle = C.rule;
ctx.beginPath();
ctx.moveTo(gx0, gy0); ctx.lineTo(gx0, gy1); ctx.lineTo(gx1, gy1); ctx.stroke();

var Bpeak = Bsurf * 1.15;
var GX = function (r) { return gx0 + (r / rmax) * (gx1 - gx0); };
var GY = function (b) { return gy1 - (b / Bpeak) * (gy1 - gy0); };

ctx.strokeStyle = C.figure;
ctx.lineWidth = 2;
ctx.beginPath();
for (var k = 0; k <= 160; k++) {
  var r = rmax * k / 160;
  var bv = r <= a ? mu0 * I * r / (2 * Math.PI * a * a) : mu0 * I / (2 * Math.PI * r);
  if (r === 0) { ctx.moveTo(GX(0), GY(0)); } else { ctx.lineTo(GX(r), GY(bv)); }
}
ctx.stroke();
ctx.lineWidth = 1;

// surface line
ctx.strokeStyle = C.faint;
ctx.setLineDash([3, 3]);
ctx.beginPath(); ctx.moveTo(GX(a), gy0); ctx.lineTo(GX(a), gy1); ctx.stroke();
ctx.setLineDash([]);

// probe marker on the curve
ctx.fillStyle = C.accent;
ctx.beginPath(); ctx.arc(GX(rp), GY(B), 4, 0, Math.PI * 2); ctx.fill();

ctx.fillStyle = C.ink;
ctx.fillText("B", gx0 + 4, gy0 + 10);
ctx.fillText("r", gx1 - 10, gy1 + 14);
ctx.fillStyle = C.faint;
ctx.fillText("surface", GX(a) + 3, gy0 + 24);
ctx.fillStyle = C.ink;
ctx.fillText("rises as r inside, falls as 1/r outside", gx0, H - 8);

out.note = "r = " + p.probe.toFixed(1) + " mm, B = " + (B * 1e6).toFixed(1) +
  " microtesla  (surface value " + (Bsurf * 1e6).toFixed(1) + ")";

ctx.font = "12px ui-sans-serif, system-ui, sans-serif";
ctx.textAlign = "left";
ctx.textBaseline = "alphabetic";

var x0 = W * 0.10, x1 = W * 0.90;
var yTop = H * 0.30, yBot = H * 0.62;

// solenoid walls: rows of turns, current out of page on top, into page on bottom
ctx.strokeStyle = C.rule;
ctx.beginPath(); ctx.moveTo(x0, yTop); ctx.lineTo(x1, yTop); ctx.stroke();
ctx.beginPath(); ctx.moveTo(x0, yBot); ctx.lineTo(x1, yBot); ctx.stroke();

var n = 14;
for (var i = 0; i < n; i++) {
  var x = x0 + (x1 - x0) * (i + 0.5) / n;
  // top: dot (out of page)
  ctx.strokeStyle = C.figure; ctx.fillStyle = C.figure;
  ctx.beginPath(); ctx.arc(x, yTop, 4.5, 0, Math.PI * 2); ctx.stroke();
  ctx.beginPath(); ctx.arc(x, yTop, 1.6, 0, Math.PI * 2); ctx.fill();
  // bottom: cross (into page)
  ctx.beginPath(); ctx.arc(x, yBot, 4.5, 0, Math.PI * 2); ctx.stroke();
  ctx.beginPath();
  ctx.moveTo(x - 3.2, yBot - 3.2); ctx.lineTo(x + 3.2, yBot + 3.2);
  ctx.moveTo(x + 3.2, yBot - 3.2); ctx.lineTo(x - 3.2, yBot + 3.2);
  ctx.stroke();
}

// interior field arrows
ctx.strokeStyle = C.accent;
ctx.lineWidth = 1.5;
for (var j = 0; j < 5; j++) {
  var ax = x0 + (x1 - x0) * (0.12 + 0.19 * j);
  var ay = (yTop + yBot) / 2;
  ctx.beginPath(); ctx.moveTo(ax, ay); ctx.lineTo(ax + 34, ay); ctx.stroke();
  ctx.beginPath();
  ctx.moveTo(ax + 34, ay); ctx.lineTo(ax + 27, ay - 4);
  ctx.lineTo(ax + 27, ay + 4); ctx.closePath();
  ctx.fillStyle = C.accent; ctx.fill();
}
ctx.lineWidth = 1;

// the Amperian rectangle
var rx0 = W * 0.32, rx1 = W * 0.62;
var ryIn = (yTop + yBot) / 2 + 14;
var ryOut = H * 0.13;
ctx.strokeStyle = C.ink;
ctx.setLineDash([5, 4]);
ctx.strokeRect(rx0, ryOut, rx1 - rx0, ryIn - ryOut);
ctx.setLineDash([]);

ctx.fillStyle = C.ink;
ctx.fillText("1  inside, along B: gives B L", rx0 + 6, ryIn - 6);
ctx.fillText("3  outside: B is about zero", rx0 + 6, ryOut - 6);
ctx.save();
ctx.translate(rx0 - 6, (ryIn + ryOut) / 2);
ctx.rotate(-Math.PI / 2);
ctx.textAlign = "center";
ctx.fillText("2, 4  perpendicular to B: zero", 0, 0);
ctx.restore();
ctx.textAlign = "left";

ctx.fillStyle = C.figure;
ctx.fillText("turns carrying I, n per metre", x0, yBot + 26);
ctx.fillStyle = C.accent;
ctx.fillText("B = mu0 n I, uniform inside", x0, H - 10);
ctx.fillStyle = C.ink;
ctx.fillText("loop encloses n L turns", rx1 + 8, ryOut + 14);

var mu0 = 4 * Math.PI * 1e-7;
var Iin = p.inner, Ish = p.shield, rp = p.probe / 1000;
var a = 0.001, b = 0.003, c = 0.005;   // metres: inner radius, shield inner, shield outer

function enc(r) {
  var e = 0;
  e += r >= a ? Iin : Iin * (r * r) / (a * a);
  if (r > b) {
    var f = r >= c ? 1 : (r * r - b * b) / (c * c - b * b);
    e -= Ish * f;
  }
  return e;
}
function field(r) { return r <= 0 ? 0 : mu0 * enc(r) / (2 * Math.PI * r); }

var B = field(rp);

ctx.font = "12px ui-sans-serif, system-ui, sans-serif";
ctx.textAlign = "left";
ctx.textBaseline = "alphabetic";

// ---- left: cross-section ----
var cx = W * 0.22, cy = H * 0.50;
var rmax = 0.008;
var pix = Math.min(W * 0.18, H * 0.40) / rmax;

ctx.strokeStyle = C.rule;
ctx.beginPath(); ctx.arc(cx, cy, c * pix, 0, Math.PI * 2); ctx.stroke();
ctx.beginPath(); ctx.arc(cx, cy, b * pix, 0, Math.PI * 2); ctx.stroke();
ctx.fillStyle = C.figure;
ctx.beginPath(); ctx.arc(cx, cy, a * pix, 0, Math.PI * 2); ctx.fill();

// shield hatching
ctx.strokeStyle = C.faint;
for (var k = 0; k < 24; k++) {
  var th = k * Math.PI * 2 / 24;
  ctx.beginPath();
  ctx.moveTo(cx + b * pix * Math.cos(th), cy + b * pix * Math.sin(th));
  ctx.lineTo(cx + c * pix * Math.cos(th), cy + c * pix * Math.sin(th));
  ctx.stroke();
}

// Amperian circle with a travelling marker
var pr = rp * pix;
ctx.strokeStyle = C.accent;
ctx.setLineDash([4, 4]);
ctx.beginPath(); ctx.arc(cx, cy, pr, 0, Math.PI * 2); ctx.stroke();
ctx.setLineDash([]);
var dir = B >= 0 ? 1 : -1;
var ang = dir * (t * 1.6) % (Math.PI * 2);
ctx.fillStyle = C.accent;
ctx.beginPath(); ctx.arc(cx + pr * Math.cos(ang), cy + pr * Math.sin(ang), 4, 0, Math.PI * 2); ctx.fill();

ctx.fillStyle = C.ink;
ctx.fillText("core  shield  gap", cx - c * pix, cy + Math.min(W * 0.18, H * 0.40) + 18);

// ---- right: B(r) ----
var gx0 = W * 0.46, gx1 = W - 14, gy0 = 18, gy1 = H - 30;
ctx.strokeStyle = C.rule;
ctx.beginPath(); ctx.moveTo(gx0, gy0); ctx.lineTo(gx0, gy1); ctx.lineTo(gx1, gy1); ctx.stroke();

var peak = 0;
for (var k2 = 1; k2 <= 200; k2++) {
  var rr = rmax * k2 / 200;
  var v = Math.abs(field(rr));
  if (v > peak) peak = v;
}
if (peak <= 0) peak = 1e-9;
peak = peak * 1.15;

var GX = function (r) { return gx0 + (r / rmax) * (gx1 - gx0); };
var GY = function (bv) { return gy1 - (bv / peak) * (gy1 - gy0); };

ctx.strokeStyle = C.figure;
ctx.lineWidth = 2;
ctx.beginPath();
for (var k3 = 1; k3 <= 200; k3++) {
  var r3 = rmax * k3 / 200;
  var b3 = Math.abs(field(r3));
  if (k3 === 1) { ctx.moveTo(GX(r3), GY(b3)); } else { ctx.lineTo(GX(r3), GY(b3)); }
}
ctx.stroke();
ctx.lineWidth = 1;

ctx.strokeStyle = C.faint;
ctx.setLineDash([3, 3]);
ctx.beginPath(); ctx.moveTo(GX(b), gy0); ctx.lineTo(GX(b), gy1); ctx.stroke();
ctx.beginPath(); ctx.moveTo(GX(c), gy0); ctx.lineTo(GX(c), gy1); ctx.stroke();
ctx.setLineDash([]);

ctx.fillStyle = C.accent;
ctx.beginPath(); ctx.arc(GX(rp), GY(Math.abs(B)), 4, 0, Math.PI * 2); ctx.fill();

ctx.fillStyle = C.ink;
ctx.fillText("B", gx0 + 4, gy0 + 10);
ctx.fillText("r", gx1 - 10, gy1 + 14);
ctx.fillStyle = C.faint;
ctx.fillText("3 mm", GX(b) + 3, gy0 + 24);
ctx.fillText("5 mm", GX(c) + 3, gy0 + 38);
ctx.fillStyle = C.ink;
ctx.fillText("outside, only the net current matters", gx0, H - 8);

out.note = "r = " + p.probe.toFixed(2) + " mm: enclosed " + enc(rp).toFixed(2) +
  " A, B = " + (Math.abs(B) * 1e6).toFixed(1) + " microtesla";

var cyc = 8;
var tc = t % cyc;
var w0 = p.omega0, al = p.alpha;
var th = w0 * tc + 0.5 * al * tc * tc;
var w = w0 + al * tc;
var R = Math.min(W * 0.30, H * 0.38);
var cx = W * 0.30, cy = H * 0.52;

ctx.font = "12px ui-sans-serif, system-ui, sans-serif";
ctx.lineWidth = 1.5;

ctx.strokeStyle = C.rule;
ctx.beginPath();
ctx.arc(cx, cy, R, 0, Math.PI * 2);
ctx.stroke();

ctx.strokeStyle = C.faint;
ctx.setLineDash([4, 4]);
ctx.beginPath();
ctx.moveTo(cx, cy);
ctx.lineTo(cx + R * 1.22, cy);
ctx.stroke();
ctx.setLineDash([]);
ctx.fillStyle = C.faint;
ctx.fillText("theta = 0", cx + R * 0.62, cy - 6);

var k;
ctx.strokeStyle = C.rule;
ctx.lineWidth = 1;
for (k = 0; k < 4; k++) {
  var a = th + k * Math.PI / 2;
  ctx.beginPath();
  ctx.moveTo(cx, cy);
  ctx.lineTo(cx + R * Math.cos(a), cy - R * Math.sin(a));
  ctx.stroke();
}

var tha = Math.min(Math.abs(th), Math.PI * 2);
var end = th > 0 ? -tha : tha;
ctx.strokeStyle = C.figure;
ctx.lineWidth = 2.5;
ctx.beginPath();
ctx.arc(cx, cy, R * 0.42, 0, end, th > 0);
ctx.stroke();
ctx.fillStyle = C.figure;
var mid = th > 0 ? tha / 2 : -tha / 2;
ctx.fillText("theta", cx + R * 0.55 * Math.cos(mid) - 8, cy - R * 0.55 * Math.sin(mid) + 4);

var mx = cx + R * Math.cos(th), my = cy - R * Math.sin(th);
var vlen = Math.min(Math.abs(w) * R * 0.075, R * 0.75);
var sgn = w >= 0 ? 1 : -1;
var tx = -Math.sin(th) * sgn, ty = -Math.cos(th) * sgn;
ctx.strokeStyle = C.accent;
ctx.lineWidth = 2;
ctx.beginPath();
ctx.moveTo(mx, my);
ctx.lineTo(mx + tx * vlen, my + ty * vlen);
ctx.stroke();
var hx = mx + tx * vlen, hy = my + ty * vlen;
ctx.beginPath();
ctx.moveTo(hx, hy);
ctx.lineTo(hx - tx * 7 - ty * 4, hy - ty * 7 + tx * 4);
