ctx.translate(fx, fy);
ctx.rotate(-th);
ctx.fillStyle = C.figure;
ctx.beginPath(); ctx.roundRect(-18, -14, 36, 14, 3); ctx.fill();
ctx.fillStyle = C.paper;
ctx.beginPath(); ctx.roundRect(-9, -12, 12, 7, 2); ctx.fill();
ctx.restore();

