ctx.beginPath(); ctx.moveTo(px, py); ctx.lineTo(px - rx, cyc); ctx.stroke();
ctx.beginPath(); ctx.moveTo(px, py); ctx.lineTo(px + rx, cyc); ctx.stroke();

