ctx.lineWidth = 2;
ctx.beginPath(); ctx.moveTo(px, py); ctx.lineTo(bx, by); ctx.stroke();
ctx.lineWidth = 1.5;
ctx.fillStyle = C.figure;
ctx.beginPath(); ctx.arc(bx, by, 8, 0, 6.2832); ctx.fill();

// labels
