ctx.textAlign = "right";
ctx.fillText("L = " + L.toFixed(2) + " m", (px + bx) / 2 - 8, (py + by) / 2);
ctx.fillStyle = C.ink;
ctx.textAlign = "left";
ctx.fillText("h = L cos" + String.fromCharCode(952) + " = " + h.toFixed(2) + " m", px + 6, py + h * pxPerM * 0.5);
ctx.textAlign = "center";
