var Z = Math.round(p.Z);
var nsel = Math.round(p.n);
var NMAX = 4;
var cx = W * 0.42, cy = H * 0.5;
var Rmax = Math.min(W * 0.36, H * 0.42);
var scale = Rmax / (NMAX * NMAX);
ctx.font = "12px ui-sans-serif, system-ui, sans-serif";
ctx.textAlign = "left";
ctx.textBaseline = "middle";

// orbits
var i;
for (i = 1; i <= NMAX; i++) {
  var R = i * i * scale;
  ctx.beginPath();
  ctx.arc(cx, cy, R, 0, Math.PI * 2);
  if (i === nsel) {
    ctx.strokeStyle = C.accent;
    ctx.lineWidth = 2;
    ctx.setLineDash([]);
  } else {
    ctx.strokeStyle = C.faint;
    ctx.lineWidth = 1;
    ctx.setLineDash([3, 4]);
