ctx.beginPath();
ctx.moveTo(hx, hy);
ctx.lineTo(hx - vx * 6 - vy * 4, hy - vy * 6 + vx * 4);
ctx.lineTo(hx - vx * 6 + vy * 4, hy - vy * 6 - vx * 4);
ctx.closePath();
ctx.fillStyle = C.figure;
ctx.fill();
ctx.lineWidth = 1;
ctx.fillStyle = C.figure;
ctx.fillText("v", hx + 6, hy - 2);

ctx.fillStyle = C.accent;
ctx.beginPath();
ctx.arc(ex, ey, 4.5, 0, Math.PI * 2);
ctx.fill();

// side panel numbers
var r_nm = 0.0529 * nsel * nsel / Z;
var v_ms = 2.19e6 * Z / nsel;
