var dSfin = Ca * Math.log(Tf / TH0) + Ca * Math.log(Tf / TC0);

ctx.font = "12px ui-sans-serif, system-ui, sans-serif";
ctx.lineWidth = 1.5;

// ---- left half: the two blocks ----
var bw = W * 0.16, bh = H * 0.30;
var by = H * 0.34;
var xA = W * 0.06, xB = W * 0.27;

function block(x, T, T0, name) {
  var hot = (T - 150) / 400;
  if (hot < 0) hot = 0; if (hot > 1) hot = 1;
  ctx.globalAlpha = 0.12 + 0.55 * hot;
  ctx.fillStyle = C.accent;
  ctx.fillRect(x, by, bw, bh);
  ctx.globalAlpha = 1;
  ctx.strokeStyle = C.ink;
  ctx.strokeRect(x, by, bw, bh);
  ctx.fillStyle = C.ink;
  ctx.textAlign = "center";
  ctx.fillText(name, x + bw / 2, by - 20);
  ctx.fillText(T.toFixed(0) + " K", x + bw / 2, by - 6);
  ctx.fillStyle = C.figure;
  ctx.fillText("start " + T0.toFixed(0) + " K", x + bw / 2, by + bh + 16);
}
block(xA, Th, TH0, "hot block");
block(xB, Tc, TC0, "cold block");

// conducting bar between them
var midY = by + bh / 2;
ctx.strokeStyle = C.rule;
ctx.lineWidth = 6;
ctx.beginPath();
ctx.moveTo(xA + bw, midY); ctx.lineTo(xB, midY); ctx.stroke();
ctx.lineWidth = 1.5;

// heat arrow, hot -> cold
if (e > 0.02) {
  var ax0 = xA + bw + 4, ax1 = xB - 4;
  ctx.strokeStyle = C.accent;
  ctx.beginPath();
  ctx.moveTo(ax0, midY - 18); ctx.lineTo(ax1, midY - 18); ctx.stroke();
  ctx.beginPath();
  ctx.moveTo(ax1, midY - 18); ctx.lineTo(ax1 - 6, midY - 22);
  ctx.lineTo(ax1 - 6, midY - 14); ctx.closePath();
  ctx.fillStyle = C.accent; ctx.fill();
  ctx.fillStyle = C.accent;
  ctx.textAlign = "center";
  ctx.fillText("Q", (ax0 + ax1) / 2, midY - 24);
}

// ---- right half: entropy of each body and the total ----
var gx = W * 0.50, gy = H * 0.14, gw = W * 0.44, gh = H * 0.66;
ctx.strokeStyle = C.rule;
ctx.beginPath(); ctx.moveTo(gx, gy); ctx.lineTo(gx, gy + gh); ctx.lineTo(gx + gw, gy + gh); ctx.stroke();

var span = Math.max(Math.abs(dSfin) * 1.6, Math.abs(Ca * Math.log(Tf / TH0)) * 1.6, 1);
var zeroY = gy + gh * 0.62;
ctx.strokeStyle = C.faint;
ctx.beginPath(); ctx.moveTo(gx, zeroY); ctx.lineTo(gx + gw, zeroY); ctx.stroke();
var YS = function (s) { return zeroY - (s / span) * (gh * 0.55); };

function curve(fn, col, dash) {
  ctx.strokeStyle = col;
  ctx.setLineDash(dash);
  ctx.beginPath();
  for (var i = 0; i <= 90; i++) {
    var u = (i / 90) * 9;
    var ee = Math.exp(-u / 2.0);
    var h = Tf + (TH0 - Tf) * ee, c = Tf - (Tf - TC0) * ee;
    var s = fn(h, c);
    var xx = gx + (i / 90) * gw;
    i === 0 ? ctx.moveTo(xx, YS(s)) : ctx.lineTo(xx, YS(s));
  }
  ctx.stroke();
  ctx.setLineDash([]);
}
curve(function (h, c) { return Ca * Math.log(h / TH0); }, C.figure, [4, 4]);
curve(function (h, c) { return Ca * Math.log(c / TC0); }, C.figure, [4, 4]);
curve(function (h, c) { return Ca * Math.log(h / TH0) + Ca * Math.log(c / TC0); }, C.accent, []);

// moving marker on the total
var mx = gx + (cyc / 9) * gw;
ctx.fillStyle = C.accent;
ctx.beginPath(); ctx.arc(mx, YS(dS), 4, 0, Math.PI * 2); ctx.fill();

ctx.fillStyle = C.ink;
ctx.textAlign = "left";
ctx.fillText("entropy change (J/K)", gx + 4, gy - 2);
ctx.fillStyle = C.figure;
ctx.fillText("hot block, falling", gx + 6, YS(-Math.abs(Ca * Math.log(Tf / TH0)) * 0.55));
ctx.fillText("cold block, rising", gx + 6, YS(Math.abs(Ca * Math.log(Tf / TC0)) * 0.75));
ctx.fillStyle = C.accent;
ctx.fillText("total", gx + gw - 34, YS(dSfin) - 8);
ctx.fillStyle = C.ink;
ctx.textAlign = "center";
ctx.fillText("time", gx + gw / 2, gy + gh + 16);

out.note = "final T " + Tf.toFixed(0) + " K,  hot block " +
  (Ca * Math.log(Tf / TH0)).toFixed(2) + " J/K,  cold block +" +
  (Ca * Math.log(Tf / TC0)).toFixed(2) + " J/K,  total +" + dSfin.toFixed(2) + " J/K";

var r = p.ratio;
ctx.font = "12px ui-sans-serif, system-ui, sans-serif";
ctx.lineWidth = 1.5;

var padL = W * 0.12, padR = W * 0.06, padT = H * 0.16, padB = H * 0.22;
var gw = W - padL - padR, gh = H - padT - padB;
var vMax = 4.2, tMax = 1.35;
var X = function (v) { return padL + (v / vMax) * gw; };
var Y = function (T) { return padT + gh - (T / tMax) * gh; };

// axes
ctx.strokeStyle = C.rule;
ctx.beginPath();
ctx.moveTo(padL, padT); ctx.lineTo(padL, padT + gh); ctx.lineTo(padL + gw, padT + gh);
ctx.stroke();
ctx.fillStyle = C.ink;
ctx.textAlign = "center";
ctx.fillText("volume", padL + gw / 2, padT + gh + 30);
ctx.save();
ctx.translate(padL - 34, padT + gh / 2);
ctx.rotate(-Math.PI / 2);
ctx.fillText("temperature", 0, 0);
ctx.restore();

var Ti = 1.0;
var xi = X(1), yi = Y(Ti), xf = X(r), yf = Y(Ti);

// isothermal reversible path
ctx.strokeStyle = C.accent;
ctx.beginPath(); ctx.moveTo(xi, yi); ctx.lineTo(xf, yf); ctx.stroke();
ctx.fillStyle = C.accent;
ctx.textAlign = "center";
ctx.fillText("slow isothermal, heat flows in", (xi + xf) / 2, yi - 12);

// detour path: adiabat down then isotherm then constant volume back up
ctx.strokeStyle = C.figure;
ctx.setLineDash([5, 4]);
ctx.beginPath();
ctx.moveTo(xi, yi);
for (var i = 0; i <= 40; i++) {
  var v = 1 + (r - 1) * (i / 40);
  var Tad = Ti * Math.pow(1 / v, 2 / 3);
  ctx.lineTo(X(v), Y(Tad));
}
ctx.lineTo(xf, yf);
ctx.stroke();
ctx.setLineDash([]);
ctx.fillStyle = C.figure;
ctx.fillText("adiabat, then reheat at fixed volume", (xi + xf) / 2, Y(Ti * Math.pow(1 / r, 2 / 3)) + 26);

// irreversible free expansion: jagged, drawn off the surface
ctx.strokeStyle = C.ink;
ctx.setLineDash([2, 3]);
ctx.beginPath();
ctx.moveTo(xi, yi);
for (var k = 1; k <= 12; k++) {
  var u = k / 12;
  var wob = Math.sin(k * 1.9) * gh * 0.11;
  ctx.lineTo(xi + (xf - xi) * u, yi - gh * 0.30 * Math.sin(Math.PI * u) + wob * (1 - u));
}
ctx.lineTo(xf, yf);
ctx.stroke();
ctx.setLineDash([]);
ctx.fillStyle = C.ink;
ctx.fillText("free expansion: no path at all", (xi + xf) / 2, yi - gh * 0.42);

// endpoints
function dot(x, y, lab, side) {
  ctx.fillStyle = C.ink;
  ctx.beginPath(); ctx.arc(x, y, 5, 0, Math.PI * 2); ctx.fill();
  ctx.textAlign = side;
  ctx.fillText(lab, x + (side === "right" ? -10 : 10), y + 18);
}
dot(xi, yi, "start: V, T", "right");
dot(xf, yf, "end: " + r.toFixed(1) + "V, same T", "left");

var dS = 8.31 * Math.log(r);
ctx.fillStyle = C.accent;
ctx.textAlign = "center";
ctx.fillText("every route between these two dots gives the same entropy change",
  padL + gw / 2, padT - 4);

out.note = "per mole, entropy change = R ln(" + r.toFixed(1) + ") = " + dS.toFixed(2) + " J/K, whichever route you invent";

var N = Math.round(p.n);
ctx.font = "12px ui-sans-serif, system-ui, sans-serif";
ctx.lineWidth = 1.5;
var kB = 1.38e-23;

function comb(n, k) {
  var r = 1;
  for (var i = 1; i <= k; i++) { r = r * (n - k + i) / i; }
  return Math.round(r);
}

var best = comb(N, Math.round(N / 2));
var padL = W * 0.08, padR = W * 0.06, padT = H * 0.30, padB = H * 0.24;
var gw = W - padL - padR, gh = H - padT - padB;
var bw = gw / (N + 1);

ctx.strokeStyle = C.rule;
ctx.beginPath();
ctx.moveTo(padL, padT + gh); ctx.lineTo(padL + gw, padT + gh); ctx.stroke();

for (var k = 0; k <= N; k++) {
  var om = comb(N, k);
  var hgt = (om / best) * gh;
  var x = padL + k * bw + bw * 0.15;
  var wid = bw * 0.7;
  ctx.fillStyle = (k === 0) ? C.figure : C.accent;
  ctx.globalAlpha = (k === 0 || k === Math.round(N / 2)) ? 0.85 : 0.35;
  ctx.fillRect(x, padT + gh - hgt, wid, hgt);
  ctx.globalAlpha = 1;
  ctx.fillStyle = C.ink;
  ctx.textAlign = "center";
  if (N <= 12) { ctx.fillText(String(om), x + wid / 2, padT + gh - hgt - 5); }
  ctx.fillStyle = C.figure;
  ctx.fillText(String(k), x + wid / 2, padT + gh + 16);
}

ctx.fillStyle = C.ink;
ctx.textAlign = "center";
ctx.fillText("number of molecules in the left half", padL + gw / 2, padT + gh + 34);
ctx.textAlign = "left";
ctx.fillText("microstates in each macrostate, for " + N + " labelled molecules", padL, padT - 34);
ctx.fillStyle = C.figure;
ctx.fillText("all on the left: 1 microstate", padL, padT - 16);

var dS = kB * Math.log(best);
out.note = "evenly split has " + best + " microstates against 1 for all-left; entropy gap = kB ln(" +
  best + ") = " + dS.toExponential(3) + " J/K";

var dB = p.dBdt, r = p.radius, N = p.turns;
var area = Math.PI * r * r;
var emf = N * area * dB;

ctx.font = "12px ui-sans-serif, system-ui, sans-serif";
ctx.lineWidth = 1;

// field region
var bx = W * 0.05, by = H * 0.13, bw = W * 0.56, bh = H * 0.74;
ctx.strokeStyle = C.faint;
ctx.strokeRect(bx, by, bw, bh);

// field magnitude cycles so the reader sees it grow and shrink
var phase = (t % 4) / 4;
var B = 0.7 + dB * (phase - 0.5) * 0.9;
if (B < 0.08) B = 0.08;
if (B > 1.5) B = 1.5;

// field symbols: crosses, size set by B
var s = 2 + B * 3.5;
ctx.strokeStyle = C.rule;
var i, j;
for (i = 0; i < 6; i++) {
  for (j = 0; j < 5; j++) {
    var fx = bx + bw * (i + 0.5) / 6;
    var fy = by + bh * (j + 0.5) / 5;
    ctx.beginPath();
    ctx.moveTo(fx - s, fy - s); ctx.lineTo(fx + s, fy + s);
    ctx.moveTo(fx - s, fy + s); ctx.lineTo(fx + s, fy - s);
    ctx.stroke();
  }
}

// the loop
var cx = bx + bw * 0.5, cy = by + bh * 0.5;
var Rp = (0.25 + 0.75 * (r - 0.02) / 0.13) * Math.min(bw, bh) * 0.40;
ctx.strokeStyle = C.accent;
ctx.lineWidth = 2.5;
ctx.beginPath();
ctx.arc(cx, cy, Rp, 0, Math.PI * 2);
ctx.stroke();

// induced current: dots running round the loop
var dir = dB > 0 ? -1 : (dB < 0 ? 1 : 0);
var speed = Math.min(Math.abs(emf) * 260, 3.0);
ctx.fillStyle = C.figure;
var k;
for (k = 0; k < 8; k++) {
  var a = k * Math.PI / 4 + dir * speed * t;
  ctx.beginPath();
  ctx.arc(cx + Rp * Math.cos(a), cy + Rp * Math.sin(a), 3.2, 0, Math.PI * 2);
  ctx.fill();
}

// arrowhead showing the sense of the current
if (dir !== 0) {
  var aa = dir * speed * t;
  var hx = cx + Rp * Math.cos(aa), hy = cy + Rp * Math.sin(aa);
  var tx = -Math.sin(aa) * dir, ty = Math.cos(aa) * dir;
  ctx.strokeStyle = C.figure;
  ctx.lineWidth = 2;
  ctx.beginPath();
  ctx.moveTo(hx, hy);
  ctx.lineTo(hx + tx * 12 - ty * 5, hy + ty * 12 + tx * 5);
  ctx.moveTo(hx, hy);
  ctx.lineTo(hx + tx * 12 + ty * 5, hy + ty * 12 - tx * 5);
  ctx.stroke();
}

ctx.fillStyle = C.ink;
ctx.fillText("B into the page", bx + 4, by - 6);
ctx.fillStyle = C.figure;
ctx.fillText(dB > 0 ? "getting stronger" : (dB < 0 ? "getting weaker" : "steady"), bx + 4, by + bh + 15);

// readout column
var tx0 = W * 0.66;
ctx.fillStyle = C.ink;
ctx.fillText("N = " + N.toFixed(0) + " turns", tx0, H * 0.26);
ctx.fillText("r = " + r.toFixed(3) + " m", tx0, H * 0.40);
ctx.fillText("A = " + area.toFixed(4) + " m2", tx0, H * 0.54);
ctx.fillStyle = C.accent;
ctx.fillText("emf = " + Math.abs(emf).toFixed(4) + " V", tx0, H * 0.68);

var word = dB > 0 ? "counterclockwise" : (dB < 0 ? "clockwise" : "none");
out.note = "dPhi/dt = " + (area * dB).toFixed(5) + " Wb/s, emf = " + Math.abs(emf).toFixed(4) + " V, induced current " + word;

var v = p.v, B = p.B, L = p.L, R = p.R;
var emf = B * L * v;
var I = emf / R;
var F = B * I * L;
var P = emf * I;

ctx.font = "12px ui-sans-serif, system-ui, sans-serif";
ctx.lineWidth = 1;

var y1 = H * 0.30, y2 = H * 0.78;
var xL = W * 0.12, xR = W * 0.92;

// field crosses between the rails
ctx.strokeStyle = C.rule;
var i, j, s = 3.5;
for (i = 0; i < 9; i++) {
  for (j = 0; j < 3; j++) {
    var fx = xL + (xR - xL) * (i + 0.5) / 9;
    var fy = y1 + (y2 - y1) * (j + 0.5) / 3;
    ctx.beginPath();
    ctx.moveTo(fx - s, fy - s); ctx.lineTo(fx + s, fy + s);
    ctx.moveTo(fx - s, fy + s); ctx.lineTo(fx + s, fy - s);
    ctx.stroke();
  }
}

// rails
ctx.strokeStyle = C.ink;
ctx.lineWidth = 2;
ctx.beginPath();
ctx.moveTo(xL, y1); ctx.lineTo(xR, y1);
ctx.moveTo(xL, y2); ctx.lineTo(xR, y2);
ctx.stroke();

// resistor on the left end
ctx.strokeStyle = C.figure;
ctx.beginPath();
ctx.moveTo(xL, y1); ctx.lineTo(xL, y1 + (y2 - y1) * 0.3);
ctx.stroke();
ctx.strokeRect(xL - 7, y1 + (y2 - y1) * 0.3, 14, (y2 - y1) * 0.4);
ctx.beginPath();
ctx.moveTo(xL, y1 + (y2 - y1) * 0.7); ctx.lineTo(xL, y2);
ctx.stroke();
ctx.fillStyle = C.figure;
ctx.fillText("R = " + R.toFixed(2) + " ohm", xL - 6, y2 + 17);

// the rod, sliding right and re-entering
var span = xR - W * 0.30;
var pos = W * 0.30 + ((t * v / 9) % 1) * span;
ctx.strokeStyle = C.accent;
ctx.lineWidth = 4;
ctx.beginPath();
ctx.moveTo(pos, y1); ctx.lineTo(pos, y2);
ctx.stroke();

// velocity arrow (right) and magnetic force on the rod (left)
var ym = (y1 + y2) / 2;
ctx.lineWidth = 2;
ctx.strokeStyle = C.ink;
var va = 14 + v * 5;
ctx.beginPath();
ctx.moveTo(pos, ym - 14); ctx.lineTo(pos + va, ym - 14);
ctx.lineTo(pos + va - 6, ym - 18); ctx.moveTo(pos + va, ym - 14);
ctx.lineTo(pos + va - 6, ym - 10);
ctx.stroke();
ctx.fillStyle = C.ink;
ctx.fillText("v = " + v.toFixed(1) + " m/s", pos + 6, ym - 20);

var fa = Math.min(10 + F * 60, 70);
ctx.strokeStyle = C.figure;
ctx.beginPath();
ctx.moveTo(pos, ym + 16); ctx.lineTo(pos - fa, ym + 16);
ctx.lineTo(pos - fa + 6, ym + 12); ctx.moveTo(pos - fa, ym + 16);
ctx.lineTo(pos - fa + 6, ym + 20);
ctx.stroke();
ctx.fillStyle = C.figure;
ctx.fillText("drag " + F.toFixed(3) + " N", pos - fa - 4, ym + 34);

ctx.fillStyle = C.ink;
ctx.fillText("B into the page, " + B.toFixed(2) + " T", xL, H * 0.16);
ctx.fillStyle = C.accent;
ctx.fillText("rod length L = " + L.toFixed(2) + " m", W * 0.52, H * 0.16);

out.note = "emf = BLv = " + emf.toFixed(3) + " V, I = " + I.toFixed(3) + " A, drag = " + F.toFixed(4) + " N, power = " + P.toFixed(3) + " W";

ctx.font = "12px ui-sans-serif, system-ui, sans-serif";
ctx.lineWidth = 2;

var wx = W * 0.16;
var yTop = H * 0.10, yBot = H * 0.92;

// the long straight wire
ctx.strokeStyle = C.accent;
ctx.beginPath();
ctx.moveTo(wx, yTop); ctx.lineTo(wx, yBot);
ctx.stroke();
// current arrow up the wire
ctx.beginPath();
ctx.moveTo(wx, yTop + 26); ctx.lineTo(wx - 5, yTop + 36);
ctx.moveTo(wx, yTop + 26); ctx.lineTo(wx + 5, yTop + 36);
ctx.stroke();
ctx.fillStyle = C.accent;
ctx.fillText("I, rising", wx - 14, yTop - 2);

// field crosses to the right of the wire, thinning with distance
ctx.strokeStyle = C.rule;
ctx.lineWidth = 1;
var i, j;
for (i = 0; i < 7; i++) {
  var fx = wx + (W * 0.78) * Math.pow((i + 0.6) / 7, 1.5);
  var sz = 6.5 / (1 + 3.2 * (fx - wx) / W);
  for (j = 0; j < 4; j++) {
    var fy = yTop + (yBot - yTop) * (j + 0.5) / 4;
    ctx.beginPath();
    ctx.moveTo(fx - sz, fy - sz); ctx.lineTo(fx + sz, fy + sz);
    ctx.moveTo(fx - sz, fy + sz); ctx.lineTo(fx + sz, fy - sz);
    ctx.stroke();
  }
}

// the loop
var x1 = W * 0.40, x2 = W * 0.82;
var ly1 = H * 0.24, ly2 = H * 0.78;
ctx.strokeStyle = C.ink;
ctx.lineWidth = 2;
ctx.strokeRect(x1, ly1, x2 - x1, ly2 - ly1);

// the thin strip dr
var sx = W * 0.56, sw = W * 0.045;
ctx.fillStyle = C.figure;
ctx.globalAlpha = 0.35;
ctx.fillRect(sx, ly1, sw, ly2 - ly1);
ctx.globalAlpha = 1;
ctx.strokeStyle = C.figure;
ctx.lineWidth = 1;
ctx.strokeRect(sx, ly1, sw, ly2 - ly1);
ctx.fillStyle = C.figure;
ctx.fillText("dr", sx + sw + 3, ly1 - 5);

// distance markers
ctx.strokeStyle = C.figure;
ctx.setLineDash([3, 3]);
ctx.beginPath();
ctx.moveTo(wx, ly2 + 16); ctx.lineTo(x1, ly2 + 16);
ctx.moveTo(wx, ly2 + 34); ctx.lineTo(x2, ly2 + 34);
ctx.moveTo(wx, ly1 - 18); ctx.lineTo(sx, ly1 - 18);
ctx.stroke();
ctx.setLineDash([]);
ctx.fillStyle = C.figure;
ctx.fillText("a", (wx + x1) / 2 - 3, ly2 + 13);
ctx.fillText("b", (wx + x2) / 2 - 3, ly2 + 31);
ctx.fillText("r", (wx + sx) / 2 - 3, ly1 - 21);

// loop height label
ctx.fillStyle = C.ink;
ctx.fillText("L", x2 + 6, (ly1 + ly2) / 2);
ctx.fillText("B = mu0 I / 2 pi r, into the page", W * 0.30, H * 0.13);
ctx.fillStyle = C.accent;
ctx.fillText("strip area = L dr", sx - 18, ly2 + 52);

var dU = p.Q - p.Wby;
ctx.font = '12px ui-sans-serif, system-ui, sans-serif';
ctx.textAlign = 'center';
ctx.textBaseline = 'middle';

var bx = W * 0.5, by = H * 0.5, bw = W * 0.30, bh = H * 0.40;

// the system box
ctx.strokeStyle = C.ink;
ctx.lineWidth = 2;
ctx.strokeRect(bx - bw / 2, by - bh / 2, bw, bh);
ctx.fillStyle = C.faint;
ctx.fillRect(bx - bw / 2, by - bh / 2, bw, bh);

ctx.fillStyle = C.ink;
ctx.fillText('the gas', bx, by - 16);
ctx.fillText('U changes by', bx, by + 4);
ctx.fillText((dU >= 0 ? '+' : '') + dU.toFixed(0) + ' J', bx, by + 22);

// arrow helper
function arrow(x1, y1, x2, y2, col) {
  ctx.strokeStyle = col;
  ctx.fillStyle = col;
  ctx.lineWidth = 2.5;
  ctx.beginPath();
  ctx.moveTo(x1, y1);
  ctx.lineTo(x2, y2);
  ctx.stroke();
  var a = Math.atan2(y2 - y1, x2 - x1);
  ctx.beginPath();
  ctx.moveTo(x2, y2);
  ctx.lineTo(x2 - 9 * Math.cos(a - 0.4), y2 - 9 * Math.sin(a - 0.4));
  ctx.lineTo(x2 - 9 * Math.cos(a + 0.4), y2 - 9 * Math.sin(a + 0.4));
  ctx.closePath();
  ctx.fill();
}

// heat arrow on the left: points in when Q > 0
var lx = bx - bw / 2, ox = W * 0.10;
var pulse = 1 + 0.12 * Math.sin(t * 2.2);
if (p.Q >= 0) { arrow(ox, by, lx - 6, by, C.accent); }
else { arrow(lx - 6, by, ox, by, C.accent); }
ctx.fillStyle = C.accent;
ctx.fillText('Q = ' + p.Q.toFixed(0) + ' J', (ox + lx) / 2, by - 20);
ctx.fillStyle = C.ink;
ctx.fillText(p.Q >= 0 ? 'heat in' : 'heat out', (ox + lx) / 2, by + 22);

// work arrow on the right: points out when W > 0
var rx = bx + bw / 2, oxr = W * 0.90;
if (p.Wby >= 0) { arrow(rx + 6, by, oxr, by, C.figure); }
else { arrow(oxr, by, rx + 6, by, C.figure); }
ctx.fillStyle = C.figure;
ctx.fillText('W = ' + p.Wby.toFixed(0) + ' J', (rx + oxr) / 2, by - 20);
ctx.fillStyle = C.ink;
