ctx.lineWidth = 1.5;

var cx = W * 0.36;
var boxW = W * 0.44, boxH = H * 0.15;
var hotY = H * 0.06, coldY = H * 0.79;
var engR = Math.min(W, H) * 0.11;
var engY = H * 0.48;

// reservoirs
ctx.strokeStyle = C.rule; ctx.fillStyle = C.paper;
ctx.beginPath(); ctx.rect(cx - boxW / 2, hotY, boxW, boxH); ctx.fill(); ctx.stroke();
ctx.beginPath(); ctx.rect(cx - boxW / 2, coldY, boxW, boxH); ctx.fill(); ctx.stroke();
ctx.fillStyle = C.ink;
ctx.fillText("hot reservoir  T_H = " + TH.toFixed(0) + " K", cx, hotY + boxH * 0.62);
ctx.fillText("cold reservoir  T_C = " + TC.toFixed(0) + " K", cx, coldY + boxH * 0.62);

// pipe widths scale with heat
var wHot = 6 + 26 * (Qh / 1000);
var wCold = 6 + 26 * (Qc / 1000);

function pipe(x, y0, y1, wid, col) {
  ctx.fillStyle = col;
  ctx.globalAlpha = 0.5;
  ctx.fillRect(x - wid / 2, y0, wid, y1 - y0);
  ctx.globalAlpha = 1;
}
pipe(cx, hotY + boxH, engY - engR, wHot, C.figure);
pipe(cx, engY + engR, coldY, wCold, C.figure);

// flowing markers so the direction is visible
var ph = (t * 0.5) % 1;
ctx.fillStyle = C.accent;
for (var k = 0; k < 3; k++) {
  var f = (ph + k / 3) % 1;
  var y1 = hotY + boxH + f * (engY - engR - hotY - boxH);
  ctx.beginPath(); ctx.arc(cx, y1, 2.5, 0, Math.PI * 2); ctx.fill();
  var y2 = engY + engR + f * (coldY - engY - engR);
  ctx.beginPath(); ctx.arc(cx, y2, 2.5, 0, Math.PI * 2); ctx.fill();
}

// engine
ctx.strokeStyle = C.accent; ctx.fillStyle = C.paper;
ctx.beginPath(); ctx.arc(cx, engY, engR, 0, Math.PI * 2); ctx.fill(); ctx.stroke();
ctx.fillStyle = C.ink; ctx.fillText("engine", cx, engY + 4);

// work arrow out to the right
var wx0 = cx + engR, wx1 = W * 0.80;
var wWid = 4 + 26 * (Wk / 1000);
ctx.fillStyle = C.accent; ctx.globalAlpha = 0.55;
ctx.fillRect(wx0, engY - wWid / 2, wx1 - wx0 - 8, wWid);
ctx.globalAlpha = 1;
ctx.beginPath();
ctx.moveTo(wx1 - 10, engY - wWid / 2 - 5);
ctx.lineTo(wx1, engY);
ctx.lineTo(wx1 - 10, engY + wWid / 2 + 5);
ctx.closePath(); ctx.fill();

ctx.fillStyle = C.ink;
ctx.textAlign = "left";
ctx.fillText("Q_H = " + Qh.toFixed(0) + " J", cx + wHot / 2 + 6, (hotY + boxH + engY - engR) / 2);
ctx.fillText("Q_C = " + Qc.toFixed(0) + " J", cx + wCold / 2 + 6, (engY + engR + coldY) / 2);
ctx.textAlign = "center";
ctx.fillText("W = " + Wk.toFixed(0) + " J", (wx0 + wx1) / 2, engY - wWid / 2 - 10);

out.note = "Carnot limit " + (eC * 100).toFixed(1) + "%, this engine " + (e * 100).toFixed(1) +
  "%, work " + Wk.toFixed(0) + " J, waste heat " + Qc.toFixed(0) + " J per 1000 J burned";

var r = p.r, g = p.gamma, kk = p.heat;
var eff = 1 - Math.pow(r, 1 - g);

// states in units where V2 = 1 and P1 = 1
var P1 = 1, V1 = r;
var P2 = Math.pow(r, g), V2 = 1;
var P3 = kk * P2, V3 = 1;
var P4 = kk, V4 = r;

var pad = 40;
var Pmax = P3 * 1.1, Vmax = r * 1.12;
var X = function (v) { return pad + (v / Vmax) * (W - pad - 14); };
var Y = function (pp) { return H - pad + 6 - (pp / Pmax) * (H - pad); };

ctx.font = "12px ui-sans-serif, system-ui, sans-serif";
ctx.lineWidth = 1.2;

// axes
ctx.strokeStyle = C.rule;
ctx.beginPath();
ctx.moveTo(pad, 8); ctx.lineTo(pad, Y(0)); ctx.lineTo(W - 8, Y(0));
ctx.stroke();
ctx.fillStyle = C.ink;
ctx.textAlign = "left";
ctx.fillText("P", pad - 26, 16);
ctx.textAlign = "right";
ctx.fillText("V", W - 8, Y(0) + 16);

function adiab(pa, va, vb, put) {
  var n = 40;
  for (var i = 0; i <= n; i++) {
    var v = va + (vb - va) * i / n;
    var pp = pa * Math.pow(va / v, g);
    if (i === 0) put(X(v), Y(pp), true); else put(X(v), Y(pp), false);
  }
}

// shade the enclosed area
ctx.fillStyle = C.faint;
ctx.globalAlpha = 0.6;
ctx.beginPath();
adiab(P1, V1, V2, function (x, y, first) { first ? ctx.moveTo(x, y) : ctx.lineTo(x, y); });
ctx.lineTo(X(V3), Y(P3));
adiab(P3, V3, V4, function (x, y) { ctx.lineTo(x, y); });
ctx.closePath(); ctx.fill();
ctx.globalAlpha = 1;

// cycle outline
ctx.strokeStyle = C.figure;
ctx.lineWidth = 2;
ctx.beginPath();
adiab(P1, V1, V2, function (x, y, first) { first ? ctx.moveTo(x, y) : ctx.lineTo(x, y); });
ctx.lineTo(X(V3), Y(P3));
adiab(P3, V3, V4, function (x, y) { ctx.lineTo(x, y); });
ctx.lineTo(X(V1), Y(P1));
ctx.stroke();

// animated dot, one second per leg
var per = 4, u = (t % per);
var dx, dy;
if (u < 1) { var v = V1 + (V2 - V1) * u; dx = X(v); dy = Y(P1 * Math.pow(V1 / v, g)); }
else if (u < 2) { dx = X(V2); dy = Y(P2 + (P3 - P2) * (u - 1)); }
else if (u < 3) { var v2 = V3 + (V4 - V3) * (u - 2); dx = X(v2); dy = Y(P3 * Math.pow(V3 / v2, g)); }
else { dx = X(V4); dy = Y(P4 + (P1 - P4) * (u - 3)); }
ctx.fillStyle = C.accent;
ctx.beginPath(); ctx.arc(dx, dy, 5, 0, Math.PI * 2); ctx.fill();

// labels
ctx.fillStyle = C.ink;
ctx.textAlign = "left";
ctx.fillText("1", X(V1) + 6, Y(P1) + 4);
ctx.fillText("4", X(V4) + 6, Y(P4) + 4);
ctx.textAlign = "right";
ctx.fillText("2", X(V2) - 6, Y(P2) + 4);
ctx.fillText("3", X(V3) - 6, Y(P3) + 4);
ctx.textAlign = "center";
ctx.fillStyle = C.figure;
ctx.fillText("adiabatic squeeze", (X(V1) + X(V2)) / 2, Y(P2) - 10);
ctx.fillText("burn, V fixed", X(V2) + 46, (Y(P2) + Y(P3)) / 2);
ctx.fillText("adiabatic push", (X(V3) + X(V4)) / 2, Y(P3 / 3) + 4);
ctx.fillText("exhaust, V fixed", X(V4) - 44, (Y(P4) + Y(P1)) / 2);

out.note = "compression ratio " + r.toFixed(1) + ", gamma " + g.toFixed(2) +
  " gives efficiency " + (eff * 100).toFixed(2) + "%  (shaded area is the net work)";

var TH = p.TH, TC = p.TC, n = p.n;
var R = 8.31, L2 = Math.log(2);
var Wh = n * R * TH * L2, Wc = n * R * TC * L2, Wnet = Wh - Wc;
var e = 1 - TC / TH; if (e < 0) e = 0;

// units: V from V0 to 2V0, P = nRT/V with V0 = 1
var pad = 40;
var Pmax = n * R * TH * 1.15, Vmax = 2.35;
var X = function (v) { return pad + ((v - 0.65) / (Vmax - 0.65)) * (W - pad - 16); };
var Y = function (pp) { return H - pad + 6 - (pp / Pmax) * (H - pad); };

ctx.font = "12px ui-sans-serif, system-ui, sans-serif";
ctx.strokeStyle = C.rule; ctx.lineWidth = 1.2;
ctx.beginPath();
ctx.moveTo(pad, 8); ctx.lineTo(pad, Y(0)); ctx.lineTo(W - 8, Y(0));
ctx.stroke();
ctx.fillStyle = C.ink;
ctx.textAlign = "left"; ctx.fillText("P", pad - 26, 16);
ctx.textAlign = "right"; ctx.fillText("V", W - 8, Y(0) + 16);

function iso(T, va, vb, put) {
  var N = 40;
  for (var i = 0; i <= N; i++) {
    var v = va + (vb - va) * i / N;
    put(X(v), Y(n * R * T / v), i === 0);
  }
}

ctx.fillStyle = C.faint; ctx.globalAlpha = 0.6;
ctx.beginPath();
iso(TH, 1, 2, function (x, y, f) { f ? ctx.moveTo(x, y) : ctx.lineTo(x, y); });
iso(TC, 2, 1, function (x, y) { ctx.lineTo(x, y); });
ctx.closePath(); ctx.fill();
ctx.globalAlpha = 1;

ctx.strokeStyle = C.figure; ctx.lineWidth = 2;
ctx.beginPath();
iso(TH, 1, 2, function (x, y, f) { f ? ctx.moveTo(x, y) : ctx.lineTo(x, y); });
iso(TC, 2, 1, function (x, y) { ctx.lineTo(x, y); });
ctx.closePath(); ctx.stroke();

// corner dots
ctx.fillStyle = C.accent;
var pts = [[1, TH], [2, TH], [2, TC], [1, TC]];
for (var i = 0; i < 4; i++) {
  ctx.beginPath(); ctx.arc(X(pts[i][0]), Y(n * R * pts[i][1] / pts[i][0]), 3.5, 0, Math.PI * 2); ctx.fill();
}

ctx.fillStyle = C.figure;
ctx.textAlign = "center";
ctx.fillText("expand hot at " + TH.toFixed(0) + " K", (X(1) + X(2)) / 2, Y(n * R * TH / 1.35) - 8);
ctx.fillText("compress cold at " + TC.toFixed(0) + " K", (X(1) + X(2)) / 2, Y(n * R * TC / 1.4) + 20);
ctx.textAlign = "right";
ctx.fillText("cool, V fixed", X(2) - 6, (Y(n * R * TH / 2) + Y(n * R * TC / 2)) / 2);
ctx.textAlign = "left";
ctx.fillText("reheat, V fixed", X(1) + 6, (Y(n * R * TH) + Y(n * R * TC)) / 2);

ctx.fillStyle = C.ink;
ctx.textAlign = "left";
ctx.fillText("V_0", X(1) - 8, Y(0) + 16);
ctx.fillText("2V_0", X(2) - 10, Y(0) + 16);

out.note = "hot leg gives out " + Wh.toFixed(0) + " J, cold leg costs " + Wc.toFixed(0) +
  " J, net work " + Wnet.toFixed(0) + " J per cycle; with a perfect regenerator the efficiency is " +
  (e * 100).toFixed(1) + "%";

var Patm = p.patm, hHg = p.hg, L1 = p.len;
ctx.font = "12px ui-sans-serif, system-ui, sans-serif";
ctx.textAlign = "center";
var scale = (H - 70) / (Patm > 100 ? Patm : 100) * 1.1;
var tubeW = Math.min(26, W * 0.07);
var ok = (Patm - hHg) > 1;
var L2 = ok ? L1 * (Patm + hHg) / (Patm - hHg) : 0;

function tube(cx, base, airLen, mercLen, closedDown, label) {
  var aPx = airLen * scale, mPx = mercLen * scale;
  var total = aPx + mPx + 18;
  // glass walls
  ctx.strokeStyle = C.rule;
  ctx.lineWidth = 1.5;
  ctx.beginPath();
  ctx.moveTo(cx - tubeW / 2, base - total);
  ctx.lineTo(cx - tubeW / 2, base);
  ctx.lineTo(cx + tubeW / 2, base);
  ctx.lineTo(cx + tubeW / 2, base - total);
  ctx.stroke();
  // seal the closed end
  ctx.strokeStyle = C.ink;
  ctx.lineWidth = 3;
  ctx.beginPath();
  if (closedDown) { ctx.moveTo(cx - tubeW / 2, base); ctx.lineTo(cx + tubeW / 2, base); }
  else { ctx.moveTo(cx - tubeW / 2, base - total); ctx.lineTo(cx + tubeW / 2, base - total); }
  ctx.stroke();
  var airTop, mercTop;
  if (closedDown) { airTop = base - aPx; mercTop = airTop - mPx; }
  else { airTop = base - total; mercTop = airTop + aPx; }
  // air column
  ctx.fillStyle = C.paper;
  ctx.fillRect(cx - tubeW / 2 + 1, closedDown ? airTop : airTop, tubeW - 2, aPx);
  ctx.strokeStyle = C.accent;
  ctx.lineWidth = 1;
  ctx.strokeRect(cx - tubeW / 2 + 1, airTop, tubeW - 2, aPx);
  // mercury
  ctx.fillStyle = C.figure;
  ctx.fillRect(cx - tubeW / 2 + 1, mercTop, tubeW - 2, mPx);
  // labels
  ctx.fillStyle = C.ink;
  ctx.fillText(label, cx, base + 16);
  ctx.textAlign = "left";
  ctx.fillStyle = C.accent;
  ctx.fillText("air " + airLen.toFixed(1) + " cm", cx + tubeW / 2 + 6, airTop + aPx / 2 + 4);
  ctx.fillStyle = C.figure;
  ctx.fillText("Hg " + mercLen.toFixed(1) + " cm", cx + tubeW / 2 + 6, mercTop + mPx / 2 + 4);
  ctx.textAlign = "center";
}

var base = H - 26;
tube(W * 0.24, base, L1, hHg, true, "closed end down");
if (ok) {
  tube(W * 0.66, base, L2, hHg, false, "closed end up");
} else {
  ctx.fillStyle = C.ink;
  ctx.fillText("mercury would be pushed out", W * 0.68, H * 0.5);
}
// pressure annotations
ctx.fillStyle = C.faint;
ctx.textAlign = "center";
ctx.fillText("P = " + (Patm + hHg).toFixed(0) + " cmHg", W * 0.24, 16);
if (ok) ctx.fillText("P = " + (Patm - hHg).toFixed(0) + " cmHg", W * 0.66, 16);

out.note = ok
  ? "P1 = " + (Patm + hHg).toFixed(1) + " cmHg, P2 = " + (Patm - hHg).toFixed(1) + " cmHg, so L2 = L1 x P1/P2 = " + L2.toFixed(2) + " cm"
  : "Impossible: the mercury column exceeds the atmosphere, so it cannot hang there.";

ctx.font = "12px ui-sans-serif, system-ui, sans-serif";
ctx.textAlign = "center";
var cols = 3;
var colW = W / cols;
var cy = H * 0.38;
var titles = ["Monatomic", "Diatomic, cool", "Diatomic, hot"];
var fs = [3, 5, 7];
var notes = ["3 translational", "3 translational + 2 rotational", "3 trans + 2 rot + 2 vibrational"];
var gam = ["5/3", "7/5", "9/7"];

function arrow(x1, y1, x2, y2, col) {
  ctx.strokeStyle = col; ctx.lineWidth = 1.5;
  ctx.beginPath(); ctx.moveTo(x1, y1); ctx.lineTo(x2, y2); ctx.stroke();
  var a = Math.atan2(y2 - y1, x2 - x1);
  ctx.beginPath();
  ctx.moveTo(x2, y2);
  ctx.lineTo(x2 - 6 * Math.cos(a - 0.4), y2 - 6 * Math.sin(a - 0.4));
  ctx.lineTo(x2 - 6 * Math.cos(a + 0.4), y2 - 6 * Math.sin(a + 0.4));
  ctx.closePath();
  ctx.fillStyle = col; ctx.fill();
}

for (var i = 0; i < cols; i++) {
  var cx = colW * (i + 0.5);
  ctx.fillStyle = C.ink;
  ctx.fillText(titles[i], cx, 18);
  if (i === 0) {
    ctx.fillStyle = C.figure;
    ctx.beginPath(); ctx.arc(cx, cy, 11, 0, 6.2832); ctx.fill();
  } else {
    var sep = i === 2 ? 26 : 22;
    ctx.fillStyle = C.figure;
    ctx.beginPath(); ctx.arc(cx - sep / 2, cy, 9, 0, 6.2832); ctx.fill();
    ctx.beginPath(); ctx.arc(cx + sep / 2, cy, 9, 0, 6.2832); ctx.fill();
    if (i === 1) {
      ctx.strokeStyle = C.rule; ctx.lineWidth = 3;
      ctx.beginPath(); ctx.moveTo(cx - sep / 2, cy); ctx.lineTo(cx + sep / 2, cy); ctx.stroke();
    } else {
      // spring bond for the vibrating case
      ctx.strokeStyle = C.rule; ctx.lineWidth = 1.5;
      ctx.beginPath(); ctx.moveTo(cx - sep / 2, cy);
      for (var k = 1; k <= 6; k++) {
        ctx.lineTo(cx - sep / 2 + sep * k / 6, cy + (k % 2 === 0 ? -5 : 5) * (k === 6 ? 0 : 1));
      }
      ctx.lineTo(cx + sep / 2, cy);
      ctx.stroke();
      arrow(cx - sep / 2 - 4, cy + 20, cx - sep / 2 - 14, cy + 20, C.accent);
      arrow(cx + sep / 2 + 4, cy + 20, cx + sep / 2 + 14, cy + 20, C.accent);
      ctx.fillStyle = C.accent;
      ctx.fillText("stretch", cx, cy + 38);
    }
  }
  // translational arrows, same for every case
  arrow(cx, cy, cx + 30, cy, C.accent);
  arrow(cx, cy, cx, cy - 26, C.accent);
  arrow(cx, cy, cx - 21, cy + 18, C.accent);
  ctx.fillStyle = C.accent;
  ctx.textAlign = "left";
  ctx.fillText("x", cx + 33, cy + 4);
  ctx.textAlign = "center";
  ctx.fillText("z", cx, cy - 31);
  ctx.fillText("y", cx - 27, cy + 26);
  if (i > 0) {
    // rotation arcs
    ctx.strokeStyle = C.ink; ctx.lineWidth = 1.2;
    ctx.beginPath(); ctx.arc(cx, cy, 24, -0.6, 0.9); ctx.stroke();
    ctx.fillStyle = C.ink;
    ctx.fillText("2 rot", cx + 38, cy - 20);
  }
  ctx.fillStyle = C.ink;
  ctx.fillText(notes[i], cx, H - 42);
  ctx.fillText("f = " + fs[i] + ",  C_V = " + (fs[i] / 2).toFixed(1) + "R", cx, H - 26);
  ctx.fillStyle = C.faint;
  ctx.fillText("gamma = " + gam[i], cx, H - 10);
  if (i < cols - 1) {
    ctx.strokeStyle = C.rule; ctx.lineWidth = 1;
    ctx.beginPath(); ctx.moveTo(colW * (i + 1), 26); ctx.lineTo(colW * (i + 1), H - 54); ctx.stroke();
  }
}

ctx.font = "12px ui-sans-serif, system-ui, sans-serif";
var g = p.gamma, r = p.ratio, T1 = p.temp;
// animate the piston in and back out
var phase = 0.5 - 0.5 * Math.cos(t * 0.7);
var x = 1 + phase * (r - 1);          // compression so far
var V = 1 / x;                        // volume in units of V1
var T = T1 * Math.pow(x, g - 1);
var P = Math.pow(x, g);               // pressure in units of P1

// ---- cylinder on the left ----
var cx0 = 14, cx1 = W * 0.42, cyTop = H * 0.22, cyBot = H * 0.62;
var pistonX = cx0 + (cx1 - cx0) * V;
ctx.fillStyle = C.paper;
ctx.fillRect(cx0, cyTop, pistonX - cx0, cyBot - cyTop);
ctx.strokeStyle = C.rule; ctx.lineWidth = 1.5;
ctx.beginPath();
ctx.moveTo(cx1, cyTop); ctx.lineTo(cx0, cyTop);
ctx.lineTo(cx0, cyBot); ctx.lineTo(cx1, cyBot);
ctx.stroke();
// gas molecules, deterministic drift inside the shrinking box
ctx.fillStyle = C.accent;
for (var i = 0; i < 16; i++) {
  var sx = ((i * 0.3793 + t * (0.18 + 0.03 * (i % 5))) % 1);
  var sy = ((i * 0.6271 + t * (0.23 + 0.04 * (i % 3))) % 1);
  sx = sx < 0.5 ? sx * 2 : 2 - sx * 2;
  sy = sy < 0.5 ? sy * 2 : 2 - sy * 2;
  var mx = cx0 + 5 + sx * (pistonX - cx0 - 10);
  var my = cyTop + 5 + sy * (cyBot - cyTop - 10);
  ctx.beginPath(); ctx.arc(mx, my, 2.4, 0, 6.2832); ctx.fill();
}
// piston
ctx.fillStyle = C.figure;
ctx.fillRect(pistonX, cyTop, 8, cyBot - cyTop);
ctx.fillRect(pistonX + 8, (cyTop + cyBot) / 2 - 3, cx1 - pistonX - 8, 6);
ctx.fillStyle = C.ink;
ctx.textAlign = "center";
ctx.fillText("insulated cylinder", (cx0 + cx1) / 2, cyTop - 10);
ctx.fillText("T = " + T.toFixed(0) + " K", (cx0 + cx1) / 2, cyBot + 20);

// ---- PV diagram on the right ----
var gx0 = W * 0.55, gx1 = W - 52, gy0 = 22, gy1 = H - 30;
var Pmax = Math.pow(r, g);
function px(v) { return gx0 + (1 - (v - 1 / r) / (1 - 1 / r)) * 0 + ((v - 1 / r) / (1 - 1 / r)) * (gx1 - gx0); }
function py(pp) { return gy1 - ((pp - 1) / (Pmax - 1)) * (gy1 - gy0); }
ctx.strokeStyle = C.rule; ctx.lineWidth = 1;
ctx.beginPath();
ctx.moveTo(gx0, gy0); ctx.lineTo(gx0, gy1); ctx.lineTo(gx1, gy1);
ctx.stroke();
ctx.fillStyle = C.faint;
ctx.textAlign = "center";
ctx.fillText("volume", (gx0 + gx1) / 2, gy1 + 18);
ctx.save();
ctx.translate(gx0 - 12, (gy0 + gy1) / 2);
ctx.rotate(-Math.PI / 2);
ctx.fillText("pressure", 0, 0);
ctx.restore();

function curve(expn, col, dash) {
  ctx.strokeStyle = col; ctx.lineWidth = 1.8;
  ctx.setLineDash(dash);
  ctx.beginPath();
  for (var i = 0; i <= 60; i++) {
    var vv = 1 / r + (1 - 1 / r) * i / 60;
    var pp = Math.pow(1 / vv, expn);
    if (i === 0) ctx.moveTo(px(vv), py(pp)); else ctx.lineTo(px(vv), py(pp));
  }
  ctx.stroke();
  ctx.setLineDash([]);
}
curve(1, C.faint, [4, 4]);
curve(g, C.accent, []);
ctx.textAlign = "left";
ctx.fillStyle = C.faint;
ctx.fillText("isotherm", gx1 - 96, py(r) - 6);
ctx.fillStyle = C.accent;
ctx.fillText("adiabat", gx1 - 46, gy0 + 22);
// moving state point
ctx.fillStyle = C.ink;
ctx.beginPath(); ctx.arc(px(V), py(P), 4, 0, 6.2832); ctx.fill();

out.note = "V1/V2 = " + r.toFixed(1) + ": final T = " + (T1 * Math.pow(r, g - 1)).toFixed(0)
  + " K and P2/P1 = " + Pmax.toFixed(1) + " (an isotherm would give only " + r.toFixed(1) + ")";

ctx.font = "12px ui-sans-serif, system-ui, sans-serif";
ctx.lineWidth = 1;
var cy = H * 0.48;
var lx = W * 0.18, rx = W * 0.72;
var rad = H * 0.20;

// solenoid body
ctx.strokeStyle = C.rule;
ctx.beginPath(); ctx.moveTo(lx, cy - rad); ctx.lineTo(rx, cy - rad); ctx.stroke();
ctx.beginPath(); ctx.moveTo(lx, cy + rad); ctx.lineTo(rx, cy + rad); ctx.stroke();

// turns
var N = 12;
ctx.strokeStyle = C.figure;
for (var k = 0; k < N; k++) {
  var x = lx + (rx - lx) * (k + 0.5) / N;
  ctx.beginPath();
  ctx.ellipse(x, cy, (rx - lx) / (N * 3.2), rad, 0, 0, Math.PI * 2);
  ctx.stroke();
}

// field lines inside
ctx.strokeStyle = C.accent;
ctx.lineWidth = 1.5;
for (var j = -1; j <= 1; j++) {
  var y = cy + j * rad * 0.45;
  ctx.beginPath(); ctx.moveTo(lx + 6, y); ctx.lineTo(rx - 6, y); ctx.stroke();
  ctx.beginPath();
  ctx.moveTo(rx - 6, y); ctx.lineTo(rx - 15, y - 4); ctx.lineTo(rx - 15, y + 4);
  ctx.closePath(); ctx.fillStyle = C.accent; ctx.fill();
}
ctx.lineWidth = 1;

// length marker
ctx.strokeStyle = C.faint;
