ctx.fillText("N (never appears in L)", cxb + nx * 44 - 30, cyb + ny * 44 - 8);

// gravity on block
arrow(cxb, cyb, cxb, cyb + 40, C.ink);
ctx.fillStyle = C.ink;
ctx.fillText("mg", cxb + 6, cyb + 38);

