ctx.fillStyle = C.paper;
ctx.fillRect(cx - cw / 2, railY - ch, cw, ch);
ctx.strokeStyle = C.ink;
ctx.lineWidth = 1.5;
ctx.strokeRect(cx - cw / 2, railY - ch, cw, ch);
ctx.fillStyle = C.ink;
ctx.fillText("M", cx - 4, railY - ch / 2 + 4);

