ctx.fillStyle = C.accent;
ctx.beginPath(); ctx.arc(bx, by, 8, 0, Math.PI * 2); ctx.fill();
ctx.fillStyle = C.ink;
ctx.fillText("m", bx + 12, by + 4);

// vertical from pivot, and theta label
ctx.strokeStyle = C.faint;
ctx.setLineDash([2, 4]);
ctx.beginPath(); ctx.moveTo(cx, railY); ctx.lineTo(cx, railY + L * scale); ctx.stroke();
ctx.setLineDash([]);
ctx.strokeStyle = C.figure;
ctx.lineWidth = 1;
ctx.beginPath();
ctx.arc(cx, railY, 30, Math.PI / 2, Math.PI / 2 - th, th > 0);
ctx.stroke();
ctx.fillStyle = C.figure;
ctx.fillText("theta", cx + (th > 0 ? 10 : -40), railY + 46);

// cart displacement arrow
ctx.strokeStyle = C.accent;
ctx.lineWidth = 1.5;
ctx.beginPath(); ctx.moveTo(mid, railY - 34); ctx.lineTo(cx, railY - 34); ctx.stroke();
ctx.beginPath();
var dir = cx >= mid ? 1 : -1;
ctx.moveTo(cx, railY - 34); ctx.lineTo(cx - dir * 6, railY - 38); ctx.lineTo(cx - dir * 6, railY - 30);
ctx.closePath(); ctx.fillStyle = C.accent; ctx.fill();
ctx.fillStyle = C.accent;
ctx.fillText("cart recoil X", mid - 30, railY - 42);

out.note = "omega = " + w.toFixed(2) + " rad/s   (fixed pivot would give " +
