// offset arrow
ctx.strokeStyle = C.accent;
ctx.lineWidth = 1.5;
ctx.beginPath();
ctx.moveTo(cx, cy);
ctx.lineTo(cx + c * sc, cy);
ctx.stroke();
ctx.fillStyle = C.accent;
ctx.beginPath();
ctx.arc(cx + c * sc, cy, 3, 0, Math.PI * 2);
ctx.fill();

ctx.fillStyle = C.ink;
ctx.textAlign = "center";
ctx.fillText("axis", cx, cy - R * sc - 24);
ctx.fillText("c = " + c.toFixed(2) + " m", cx + c * sc * 0.5, cy - 12);
ctx.fillText("hole radius a = " + a.toFixed(2) + " m", cx, cy + R * sc + 26);

// ---- the bookkeeping, drawn as three bars ----
var bx = W * 0.56;
var bw = W * 0.34;
var rowY = [H * 0.26, H * 0.48, H * 0.70];
var vals = [Ifull, Ihole, Inet];
var tags = ["full disk", "piece removed", "what is left"];
var scaleBar = bw / Ifull;

for (var i = 0; i < 3; i++) {
  ctx.fillStyle = C.faint;
  ctx.fillRect(bx, rowY[i] - 9, bw, 18);
  ctx.fillStyle = i === 1 ? C.rule : C.accent;
  ctx.fillRect(bx, rowY[i] - 9, Math.max(vals[i] * scaleBar, 1), 18);
  ctx.fillStyle = C.ink;
  ctx.textAlign = "left";
  ctx.fillText(tags[i], bx, rowY[i] - 22);
  ctx.textAlign = "right";
  ctx.fillText(vals[i].toFixed(4), bx + bw, rowY[i] - 22);
}

ctx.textAlign = "left";
ctx.fillStyle = C.ink;
ctx.fillText("I about the central axis (kg m^2)", bx, H * 0.10);

out.note = "m_hole = " + mHole.toFixed(3) + " kg,  I_hole = 0.5 m a^2 + m c^2 = " +
  (0.5 * mHole * a * a).toFixed(4) + " + " + (mHole * c * c).toFixed(4) +
  " = " + Ihole.toFixed(4) + ",  I = " + Ifull.toFixed(4) + " - " + Ihole.toFixed(4) +
  " = " + Inet.toFixed(4) + " kg m^2";

var m = p.m, v = p.v, dt = p.dt;
var dp = m * v;
var F = dp / dt;

var floor = H * 0.74;
var padX = W * 0.72;
ctx.lineWidth = 1;

// timeline: approach, then stop over dt (shown slowed), then reset
var approach = 1.6;
var stopShown = 1.2;
var hold = 0.9;
var cycle = approach + stopShown + hold;
var now = t % cycle;

var startX = W * 0.12;
var x, squash;
if (now < approach) {
  x = startX + (padX - startX) * (now / approach);
  squash = 0;
} else if (now < approach + stopShown) {
  var f = (now - approach) / stopShown;
  squash = 1 - (1 - f) * (1 - f);
  x = padX + 18 * squash;
} else {
  squash = 1;
  x = padX + 18;
}

// ground line
ctx.strokeStyle = C.faint;
ctx.beginPath(); ctx.moveTo(0, floor + 26); ctx.lineTo(W, floor + 26); ctx.stroke();

// the hand / pad, drawn as a spring-like cushion
var padDepth = 14 + 26 * (dt / 0.5);
var padLeft = padX + 18 - padDepth * (1 - squash) * 0 + 14;
ctx.strokeStyle = C.rule;
ctx.lineWidth = 2;
ctx.beginPath();
var segs = 8;
for (var i = 0; i <= segs; i++) {
  var yy = floor - 22 + (44 * i) / segs;
  var xx = padLeft + ((i % 2 === 0) ? 0 : padDepth * (1 - 0.55 * squash));
  if (i === 0) ctx.moveTo(xx, yy); else ctx.lineTo(xx, yy);
}
ctx.stroke();
ctx.beginPath();
ctx.moveTo(padLeft + padDepth + 10, floor - 30);
ctx.lineTo(padLeft + padDepth + 10, floor + 26);
ctx.stroke();
ctx.lineWidth = 1;

// the ball
var r = 8 + m * 12;
if (r > 22) r = 22;
ctx.fillStyle = C.figure;
ctx.beginPath(); ctx.arc(x, floor, r, 0, Math.PI * 2); ctx.fill();

ctx.font = "12px ui-sans-serif, system-ui, sans-serif";
ctx.textAlign = "center";
ctx.fillStyle = C.ink;
ctx.fillText("m = " + m.toFixed(2) + " kg", x, floor - r - 8);

// velocity arrow while approaching
function arrow(x0, y0, x1, y1, col) {
  ctx.strokeStyle = col;
  ctx.beginPath();
  ctx.moveTo(x0, y0); ctx.lineTo(x1, y1);
  var a = Math.atan2(y1 - y0, x1 - x0);
  ctx.lineTo(x1 - 7 * Math.cos(a - 0.4), y1 - 7 * Math.sin(a - 0.4));
  ctx.moveTo(x1, y1);
  ctx.lineTo(x1 - 7 * Math.cos(a + 0.4), y1 - 7 * Math.sin(a + 0.4));
  ctx.stroke();
}

if (now < approach) {
  var alen = 6 + v * 3;
  if (alen > 70) alen = 70;
  arrow(x + r + 4, floor, x + r + 4 + alen, floor, C.accent);
  ctx.fillStyle = C.accent;
  ctx.textAlign = "left";
  ctx.fillText("v = " + v.toFixed(1) + " m/s", x + r + 8, floor - 10);
} else {
  // force arrow back on the ball, length proportional to F
  var flen = F * 0.06;
  if (flen > 90) flen = 90;
  if (flen < 8) flen = 8;
  arrow(x - r - 4, floor, x - r - 4 - flen, floor, C.accent);
  ctx.fillStyle = C.accent;
  ctx.textAlign = "right";
  ctx.fillText("average force " + F.toFixed(0) + " N", x - r - 8, floor - 10);
}

ctx.fillStyle = C.ink;
ctx.textAlign = "left";
ctx.font = "12px ui-sans-serif, system-ui, sans-serif";
ctx.fillText("stopping time " + dt.toFixed(2) + " s", 10, 18);
ctx.fillText("change in momentum " + dp.toFixed(2) + " kg m/s (fixed by m and v)", 10, 34);

out.note = "Dp = mv = " + dp.toFixed(2) + " kg m/s,  F = Dp/Dt = " + F.toFixed(1) + " N";

var F0 = p.F0, T = p.T;
var J = 2 * F0 * T / Math.PI;
var Fbar = 2 * F0 / Math.PI;

var L = 54, R = W - 18, B = H - 34, Top = 22;
var pw = R - L, ph = B - Top;

// axes
ctx.strokeStyle = C.rule;
ctx.lineWidth = 1;
ctx.beginPath();
ctx.moveTo(L, Top); ctx.lineTo(L, B); ctx.lineTo(R, B);
ctx.stroke();

var Fmax = 1000;
function px(tt) { return L + (tt / 0.06) * pw; }
function py(FF) { return B - (FF / Fmax) * ph; }

// sweep of the shaded area with t
var frac = (t % 4) / 2.6;
if (frac > 1) frac = 1;
var tEnd = T * frac;

// filled impulse area
ctx.fillStyle = C.faint;
ctx.beginPath();
ctx.moveTo(px(0), py(0));
for (var i = 0; i <= 120; i++) {
  var tt = tEnd * i / 120;
  ctx.lineTo(px(tt), py(F0 * Math.sin(Math.PI * tt / T)));
}
ctx.lineTo(px(tEnd), py(0));
ctx.closePath();
ctx.fill();

// the curve itself
ctx.strokeStyle = C.figure;
ctx.lineWidth = 2;
ctx.beginPath();
for (var k = 0; k <= 160; k++) {
  var s = T * k / 160;
  var yv = F0 * Math.sin(Math.PI * s / T);
  if (k === 0) ctx.moveTo(px(s), py(yv)); else ctx.lineTo(px(s), py(yv));
}
ctx.stroke();
ctx.lineWidth = 1;

// equal-area rectangle at the average force
ctx.strokeStyle = C.accent;
ctx.setLineDash([4, 3]);
ctx.beginPath();
ctx.moveTo(px(0), py(Fbar)); ctx.lineTo(px(T), py(Fbar));
ctx.lineTo(px(T), py(0));
ctx.stroke();
ctx.setLineDash([]);

ctx.font = "12px ui-sans-serif, system-ui, sans-serif";
ctx.fillStyle = C.accent;
ctx.textAlign = "left";
ctx.fillText("average force " + Fbar.toFixed(0) + " N", px(0) + 6, py(Fbar) - 6);

ctx.fillStyle = C.ink;
ctx.textAlign = "center";
ctx.fillText("time t (s)", (L + R) / 2, H - 8);
ctx.save();
ctx.translate(14, (Top + B) / 2);
ctx.rotate(-Math.PI / 2);
ctx.fillText("force F (N)", 0, 0);
ctx.restore();

ctx.textAlign = "right";
ctx.fillText("1000", L - 6, py(1000) + 4);
ctx.fillText("0", L - 6, py(0) + 4);
ctx.textAlign = "center";
ctx.fillText("0", L, B + 16);
ctx.fillText(T.toFixed(3), px(T), B + 16);

ctx.fillStyle = C.figure;
ctx.textAlign = "left";
ctx.fillText("area swept = impulse so far", L + 8, Top + 4);

out.note = "peak " + F0.toFixed(0) + " N, contact " + T.toFixed(3) + " s -> J = 2 F0 T / pi = " + J.toFixed(2) + " N s";

var mdot = p.mdot, v = p.v, rev = p.rev;
var F = mdot * v * (1 + rev);

var wallX = W * 0.62;
var mid = H * 0.5;

// wall or vane
ctx.strokeStyle = C.rule;
ctx.lineWidth = 3;
ctx.beginPath();
if (rev < 0.5) {
  ctx.moveTo(wallX, mid - 52); ctx.lineTo(wallX, mid + 52);
} else {
  ctx.arc(wallX - 26, mid, 26, -Math.PI / 2, Math.PI / 2);
}
ctx.stroke();
ctx.lineWidth = 1;

// droplets, evenly spaced, moving at v
var n = 9;
var speed = v * 8;
for (var i = 0; i < n; i++) {
  var phase = ((t * speed + i * 26) % (wallX - 20));
  var x = 16 + phase;
  ctx.fillStyle = C.figure;
  ctx.beginPath(); ctx.arc(x, mid - 9, 4, 0, Math.PI * 2); ctx.fill();
}
// outgoing water
for (var j = 0; j < n; j++) {
  var ph2 = ((t * speed + j * 26) % (wallX - 20));
  if (rev < 0.5) {
    ctx.fillStyle = C.faint;
    ctx.beginPath(); ctx.arc(wallX - 7, mid + ph2 * 0.5, 4, 0, Math.PI * 2); ctx.fill();
  } else {
    ctx.fillStyle = C.faint;
    ctx.beginPath(); ctx.arc(wallX - 20 - ph2, mid + 9, 4, 0, Math.PI * 2); ctx.fill();
  }
}

function arrow(x0, y0, x1, y1, col) {
  ctx.strokeStyle = col;
  ctx.beginPath();
  ctx.moveTo(x0, y0); ctx.lineTo(x1, y1);
  var a = Math.atan2(y1 - y0, x1 - x0);
  ctx.lineTo(x1 - 8 * Math.cos(a - 0.4), y1 - 8 * Math.sin(a - 0.4));
  ctx.moveTo(x1, y1);
  ctx.lineTo(x1 - 8 * Math.cos(a + 0.4), y1 - 8 * Math.sin(a + 0.4));
  ctx.stroke();
}

var flen = F * 0.35;
if (flen > 110) flen = 110;
arrow(wallX + 8, mid, wallX + 8 + flen, mid, C.accent);

ctx.font = "12px ui-sans-serif, system-ui, sans-serif";
ctx.fillStyle = C.accent;
ctx.textAlign = "left";
ctx.fillText("force on the surface " + F.toFixed(0) + " N", wallX + 10, mid - 12);

ctx.fillStyle = C.ink;
ctx.fillText("water in: " + mdot.toFixed(1) + " kg/s at " + v.toFixed(0) + " m/s", 12, 18);
ctx.fillText(rev < 0.5 ? "flat wall: water leaves sideways, no rebound" : "curved vane: water leaves backwards at the same speed", 12, H - 10);

out.note = "F = (dm/dt) x change in speed = " + mdot.toFixed(1) + " x " + (v * (1 + rev)).toFixed(1) + " = " + F.toFixed(1) + " N";

var T = 8, pad = 26;
var xf = function (s) { return p.v0 * s + 0.5 * p.a * s * s; };
var vf = function (s) { return p.v0 + p.a * s; };
var xLo = 0, xHi = 0, vLo = 0, vHi = 0, s;
for (s = 0; s <= T; s += 0.05) {
  xLo = Math.min(xLo, xf(s)); xHi = Math.max(xHi, xf(s));
  vLo = Math.min(vLo, vf(s)); vHi = Math.max(vHi, vf(s));
}
if (xHi - xLo < 1) xHi = xLo + 1;
if (vHi - vLo < 1) vHi = vLo + 1;
var now = t % T;
ctx.font = "11px ui-sans-serif, system-ui, sans-serif";
ctx.textAlign = "left";

// ---- top: the track
var trackY = H * 0.30;
var PX = function (val) { return pad + (val - xLo) / (xHi - xLo) * (W - 2 * pad); };
ctx.strokeStyle = C.rule; ctx.lineWidth = 1;
ctx.beginPath(); ctx.moveTo(pad, trackY); ctx.lineTo(W - pad, trackY); ctx.stroke();
ctx.fillStyle = C.faint;
for (s = 0; s <= T + 0.001; s += 0.5) {
  ctx.beginPath(); ctx.arc(PX(xf(s)), trackY, 2, 0, Math.PI * 2); ctx.fill();
}
ctx.fillStyle = C.ink;
ctx.fillText("position on the track (dots = every 0.5 s)", pad, trackY - 14);
var cx = PX(xf(now));
ctx.fillStyle = C.accent;
ctx.fillRect(cx - 7, trackY - 6, 14, 12);
// velocity arrow on the cart
var vnow = vf(now);
var arrow = vnow / Math.max(Math.abs(vLo), Math.abs(vHi)) * (W * 0.16);
ctx.strokeStyle = C.figure; ctx.lineWidth = 2;
ctx.beginPath(); ctx.moveTo(cx, trackY - 12); ctx.lineTo(cx + arrow, trackY - 12); ctx.stroke();
if (Math.abs(arrow) > 4) {
  var sg = arrow > 0 ? 1 : -1;
  ctx.beginPath();
  ctx.moveTo(cx + arrow, trackY - 12);
  ctx.lineTo(cx + arrow - 6 * sg, trackY - 15);
  ctx.lineTo(cx + arrow - 6 * sg, trackY - 9);
  ctx.closePath(); ctx.fillStyle = C.figure; ctx.fill();
}
ctx.fillStyle = C.figure;
ctx.fillText("v", cx + arrow / 2 - 3, trackY - 17);

// ---- bottom: the v-t graph, shaded to the current time
var gTop = H * 0.46, gBot = H - 20;
var GX = function (sec) { return pad + sec / T * (W - 2 * pad); };
var GY = function (val) { return gBot - (val - vLo) / (vHi - vLo) * (gBot - gTop); };
ctx.strokeStyle = C.rule; ctx.lineWidth = 1;
ctx.beginPath(); ctx.moveTo(GX(0), gTop); ctx.lineTo(GX(0), gBot); ctx.stroke();
ctx.beginPath(); ctx.moveTo(GX(0), GY(0)); ctx.lineTo(GX(T), GY(0)); ctx.stroke();

ctx.globalAlpha = 0.25;
ctx.fillStyle = C.accent;
ctx.beginPath();
ctx.moveTo(GX(0), GY(0));
for (s = 0; s <= now; s += 0.02) ctx.lineTo(GX(s), GY(vf(s)));
ctx.lineTo(GX(now), GY(0));
ctx.closePath(); ctx.fill();
ctx.globalAlpha = 1;

ctx.strokeStyle = C.figure; ctx.lineWidth = 2;
ctx.beginPath();
for (s = 0; s <= T; s += 0.05) {
  var gx = GX(s), gy = GY(vf(s));
  if (s === 0) ctx.moveTo(gx, gy); else ctx.lineTo(gx, gy);
}
ctx.stroke();
ctx.fillStyle = C.accent;
ctx.beginPath(); ctx.arc(GX(now), GY(vf(now)), 4, 0, Math.PI * 2); ctx.fill();
ctx.fillStyle = C.ink;
ctx.fillText("v (m/s)", GX(0) + 5, gTop + 10);
ctx.fillText("t (s)", GX(T) - 26, GY(0) - 6);
ctx.fillText("shaded area = displacement", GX(0) + 5, gBot - 4);

out.note = "t = " + now.toFixed(2) + " s   v = " + vf(now).toFixed(2) +
  " m/s   x = " + xf(now).toFixed(2) + " m";

var pad = 40, gTop = 28, gBot = H - 30;
var T = 6;
var v0 = p.v0, a = p.a;
var vEnd = v0 + a * T;
var vHi = Math.max(v0, vEnd, 0) * 1.15 + 1;
var vLo = Math.min(v0, vEnd, 0) * 1.15;
if (vHi - vLo < 1) vHi = vLo + 1;
var GX = function (s) { return pad + s / T * (W - pad - 30); };
var GY = function (v) { return gBot - (v - vLo) / (vHi - vLo) * (gBot - gTop); };
ctx.font = "12px ui-sans-serif, system-ui, sans-serif";
ctx.textAlign = "left";

ctx.strokeStyle = C.rule; ctx.lineWidth = 1;
ctx.beginPath(); ctx.moveTo(GX(0), gTop); ctx.lineTo(GX(0), gBot); ctx.stroke();
ctx.beginPath(); ctx.moveTo(GX(0), GY(0)); ctx.lineTo(GX(T) + 14, GY(0)); ctx.stroke();
ctx.fillStyle = C.ink;
ctx.fillText("v", GX(0) - 14, gTop + 8);
ctx.fillText("t", GX(T) + 16, GY(0) + 4);

// the trapezoid
ctx.globalAlpha = 0.22;
ctx.fillStyle = C.accent;
ctx.beginPath();
ctx.moveTo(GX(0), GY(0));
ctx.lineTo(GX(0), GY(v0));
ctx.lineTo(GX(T), GY(vEnd));
ctx.lineTo(GX(T), GY(0));
ctx.closePath(); ctx.fill();
ctx.globalAlpha = 1;

ctx.strokeStyle = C.figure; ctx.lineWidth = 2;
ctx.beginPath(); ctx.moveTo(GX(0), GY(v0)); ctx.lineTo(GX(T), GY(vEnd)); ctx.stroke();

// dashed helpers
ctx.strokeStyle = C.rule; ctx.lineWidth = 1;
ctx.beginPath(); ctx.moveTo(GX(0), GY(vEnd)); ctx.lineTo(GX(T), GY(vEnd)); ctx.stroke();
ctx.beginPath(); ctx.moveTo(GX(T), GY(0)); ctx.lineTo(GX(T), GY(vEnd)); ctx.stroke();

// the "at" riser
ctx.strokeStyle = C.accent; ctx.lineWidth = 2;
ctx.beginPath(); ctx.moveTo(GX(T) - 2, GY(v0)); ctx.lineTo(GX(T) - 2, GY(vEnd)); ctx.stroke();
ctx.beginPath(); ctx.moveTo(GX(0), GY(v0)); ctx.lineTo(GX(T), GY(v0)); ctx.stroke();

ctx.fillStyle = C.ink;
ctx.fillText("v0", GX(0) - 24, GY(v0) + 4);
ctx.fillText("v = v0 + at", GX(T) + 4, GY(vEnd) + 4);
ctx.fillStyle = C.accent;
ctx.fillText("rise = a t", GX(T) - 66, (GY(v0) + GY(vEnd)) / 2 + 4);
ctx.fillStyle = C.ink;
ctx.fillText("area = displacement", GX(T) * 0.30, (GY(0) + GY(v0)) / 2 + 10);
ctx.fillText("base = t", GX(T) / 2 - 22, GY(0) + 16);

var disp = (v0 + vEnd) / 2 * T;
out.note = "over t = 6.0 s:  v goes " + v0.toFixed(1) + " to " + vEnd.toFixed(1) +
  " m/s,  displacement = (v0 + v)/2 x t = " + disp.toFixed(1) + " m";

var g = 10;
var h0 = p.h, u = p.u;
var tLand = (u + Math.sqrt(u * u + 2 * g * h0)) / g;
var cycle = tLand + 1.2;
var now = t % cycle;
var s = Math.min(now, tLand);
var y = h0 + u * s - 0.5 * g * s * s;
var v = u - g * s;
var apexT = u / g;
var apexY = h0 + u * u / (2 * g);
var top = Math.max(apexY, h0) * 1.12 + 2;
var pad = 34, ground = H - 26;
var PY = function (m) { return ground - m / top * (ground - 18); };
ctx.font = "11px ui-sans-serif, system-ui, sans-serif";
ctx.textAlign = "left";

// ground
ctx.strokeStyle = C.rule; ctx.lineWidth = 1;
ctx.beginPath(); ctx.moveTo(0, ground); ctx.lineTo(W, ground); ctx.stroke();
ctx.fillStyle = C.faint;
ctx.fillText("ground, y = 0", 6, ground + 14);

// height axis
ctx.beginPath(); ctx.moveTo(pad, ground); ctx.lineTo(pad, 14); ctx.stroke();
ctx.fillStyle = C.ink;
for (var m = 0; m <= top; m += Math.max(10, Math.round(top / 5 / 10) * 10)) {
  ctx.beginPath(); ctx.moveTo(pad - 4, PY(m)); ctx.lineTo(pad, PY(m)); ctx.stroke();
  ctx.fillText(m.toFixed(0), pad - 26, PY(m) + 4);
}
ctx.fillText("y (m)", pad - 28, 12);

// release point marker
var bx = W * 0.45;
ctx.strokeStyle = C.rule;
ctx.beginPath(); ctx.moveTo(pad, PY(h0)); ctx.lineTo(W - 10, PY(h0)); ctx.stroke();
ctx.fillStyle = C.faint;
ctx.fillText("release height " + h0.toFixed(0) + " m", W - 150, PY(h0) - 6);

// the balloon keeps rising
var by = h0 + u * s;
ctx.strokeStyle = C.figure; ctx.lineWidth = 2;
ctx.beginPath(); ctx.arc(bx, PY(by), 9, 0, Math.PI * 2); ctx.stroke();
ctx.fillStyle = C.figure;
ctx.fillText("balloon, steady " + u.toFixed(1) + " m/s up", bx + 14, PY(by) + 4);

// trail of the bag
ctx.fillStyle = C.faint;
for (var k = 0; k <= s; k += 0.1) {
  var yy = h0 + u * k - 0.5 * g * k * k;
  ctx.beginPath(); ctx.arc(bx - 26, PY(yy), 1.5, 0, Math.PI * 2); ctx.fill();
}
// the bag
ctx.fillStyle = C.accent;
ctx.beginPath(); ctx.arc(bx - 26, PY(Math.max(y, 0)), 5, 0, Math.PI * 2); ctx.fill();
ctx.fillText("sandbag", bx - 26 - 58, PY(Math.max(y, 0)) + 4);

// apex marker
ctx.strokeStyle = C.accent; ctx.lineWidth = 1;
ctx.beginPath(); ctx.moveTo(bx - 44, PY(apexY)); ctx.lineTo(bx - 8, PY(apexY)); ctx.stroke();
ctx.fillStyle = C.accent;
ctx.fillText("apex " + apexY.toFixed(1) + " m at t = " + apexT.toFixed(2) + " s", bx - 26 + 16, PY(apexY) - 6);

out.note = "t = " + s.toFixed(2) + " s   y = " + Math.max(y, 0).toFixed(1) +
  " m   v = " + (s < tLand ? v.toFixed(1) : "impact " + v.toFixed(1)) +
  " m/s   lands at t = " + tLand.toFixed(2) + " s";

var pad = 34, top = 16, bot = H - 30;
var T = p.T;
var vfn = function (s) { return p.v0 + p.a * s; };
var vLo = Math.min(0, vfn(0), vfn(T)), vHi = Math.max(0, vfn(0), vfn(T));
if (vHi - vLo < 1) vHi = vLo + 1;
var padv = (vHi - vLo) * 0.15;
vLo = vLo - padv; vHi = vHi + padv;
var X = function (s) { return pad + s / T * (W - pad - 18); };
var Y = function (v) { return bot - (v - vLo) / (vHi - vLo) * (bot - top); };
var zero = Y(0);
var now = t % T;

ctx.font = "12px ui-sans-serif, system-ui, sans-serif";

// shaded signed area up to the sweep line
var step = T / 240;
for (var s = 0; s < now; s += step) {
  var v = vfn(s + step / 2);
  ctx.fillStyle = v >= 0 ? C.accent : C.figure;
  ctx.globalAlpha = 0.25;
  ctx.fillRect(X(s), Math.min(zero, Y(v)), Math.max(1, X(s + step) - X(s)) + 0.5, Math.abs(Y(v) - zero));
  ctx.globalAlpha = 1;
}

// axes
ctx.strokeStyle = C.rule; ctx.lineWidth = 1;
ctx.beginPath(); ctx.moveTo(pad, top); ctx.lineTo(pad, bot); ctx.stroke();
ctx.beginPath(); ctx.moveTo(pad, zero); ctx.lineTo(X(T), zero); ctx.stroke();

// the v(t) line
ctx.strokeStyle = C.accent; ctx.lineWidth = 2;
ctx.beginPath(); ctx.moveTo(X(0), Y(vfn(0))); ctx.lineTo(X(T), Y(vfn(T))); ctx.stroke();

// sweep line
ctx.strokeStyle = C.ink; ctx.lineWidth = 1;
ctx.beginPath(); ctx.moveTo(X(now), top); ctx.lineTo(X(now), bot); ctx.stroke();
ctx.fillStyle = C.ink;
ctx.beginPath(); ctx.arc(X(now), Y(vfn(now)), 3.5, 0, Math.PI * 2); ctx.fill();

// labels
ctx.fillStyle = C.ink;
ctx.textAlign = "left";
ctx.fillText("v (m/s)", pad + 4, top + 10);
ctx.textAlign = "right";
ctx.fillText("t (s)", X(T), bot + 18);
