var pad = 36, top = 18, bot = H - 34;
var t1 = p.tup, t2 = p.tup + p.thold, t3 = p.tup + p.thold + p.tdown;
var T = Math.max(t3, 1);
var vmax = p.vmax;
var X = function (s) { return pad + s / T * (W - pad - 18); };
var Y = function (v) { return bot - v / (vmax * 1.2) * (bot - top); };

ctx.font = "12px ui-sans-serif, system-ui, sans-serif";

var now = t % (T + 1.2);
var vnow = now < t1 ? vmax * now / Math.max(t1, 0.001)
  : (now < t2 ? vmax : (now < t3 ? vmax * (t3 - now) / Math.max(p.tdown, 0.001) : 0));
if (now > t3) now = t3;

// filled area up to the sweep
ctx.fillStyle = C.accent; ctx.globalAlpha = 0.25;
ctx.beginPath();
ctx.moveTo(X(0), Y(0));
var stp = T / 240;
for (var s = 0; s <= now; s += stp) {
  var v = s < t1 ? vmax * s / Math.max(t1, 0.001)
    : (s < t2 ? vmax : vmax * (t3 - s) / Math.max(p.tdown, 0.001));
  ctx.lineTo(X(s), Y(v));
}
ctx.lineTo(X(now), Y(0));
ctx.closePath(); ctx.fill();
ctx.globalAlpha = 1;

// axes
ctx.strokeStyle = C.rule; ctx.lineWidth = 1;
ctx.beginPath(); ctx.moveTo(pad, top); ctx.lineTo(pad, bot); ctx.stroke();
ctx.beginPath(); ctx.moveTo(pad, bot); ctx.lineTo(X(T), bot); ctx.stroke();

// trapezoid outline
ctx.strokeStyle = C.accent; ctx.lineWidth = 2;
ctx.beginPath();
ctx.moveTo(X(0), Y(0)); ctx.lineTo(X(t1), Y(vmax));
ctx.lineTo(X(t2), Y(vmax)); ctx.lineTo(X(t3), Y(0));
ctx.stroke();

// dashed guides for the three pieces
ctx.strokeStyle = C.faint; ctx.lineWidth = 1;
ctx.beginPath(); ctx.moveTo(X(t1), Y(0)); ctx.lineTo(X(t1), Y(vmax)); ctx.stroke();
ctx.beginPath(); ctx.moveTo(X(t2), Y(0)); ctx.lineTo(X(t2), Y(vmax)); ctx.stroke();

// sweep
ctx.strokeStyle = C.ink; ctx.lineWidth = 1;
ctx.beginPath(); ctx.moveTo(X(now), top); ctx.lineTo(X(now), bot); ctx.stroke();
ctx.fillStyle = C.ink;
ctx.beginPath(); ctx.arc(X(now), Y(vnow), 3.5, 0, Math.PI * 2); ctx.fill();

ctx.fillStyle = C.ink;
ctx.textAlign = "left";
ctx.fillText("v (m/s)", pad + 4, top + 10);
ctx.textAlign = "right";
ctx.fillText("t (s)", X(T), bot + 20);
