const B = p.B, L = p.L, v = p.v, R = p.R;
const emf = B * L * v, I = emf / R, F = B * I * L, P = emf * I;

const pad = 34;
const yTop = pad + 10, yBot = H - pad - 14;
const xL = pad + 18, xR = W - pad;

// rails
ctx.lineWidth = 2;
ctx.strokeStyle = C.rule;
ctx.beginPath(); ctx.moveTo(xL, yTop); ctx.lineTo(xR, yTop); ctx.stroke();
ctx.beginPath(); ctx.moveTo(xL, yBot); ctx.lineTo(xR, yBot); ctx.stroke();

// resistor box on the left end
const bw = 26, bh = 14;
ctx.strokeStyle = C.ink;
ctx.beginPath(); ctx.moveTo(xL, yTop); ctx.lineTo(xL, (yTop + yBot) / 2 - bh); ctx.stroke();
ctx.beginPath(); ctx.moveTo(xL, yBot); ctx.lineTo(xL, (yTop + yBot) / 2 + bh); ctx.stroke();
ctx.strokeRect(xL - bw / 2, (yTop + yBot) / 2 - bh, bw, 2 * bh);
