const px = cx + rr * Math.cos(ang), py = cy - rr * Math.sin(ang);
ctx.fillStyle = C.figure;
ctx.beginPath(); ctx.arc(px, py, 3, 0, Math.PI * 2); ctx.fill();
ctx.strokeStyle = C.figure; ctx.lineWidth = 2;
const tx = -Math.sin(ang), ty = -Math.cos(ang);
ctx.beginPath(); ctx.moveTo(px, py); ctx.lineTo(px + 30 * tx, py + 30 * ty); ctx.stroke();
ctx.fillStyle = C.figure;
ctx.textAlign = "left";
ctx.fillText("speed w r", px + 30 * tx + 5, py + 30 * ty);

// labels
