ctx.strokeStyle = C.rule;
ctx.setLineDash([3, 5]);
ctx.beginPath();
ctx.moveTo(eqX, midY - half - 18); ctx.lineTo(eqX, midY + half + 4);
ctx.moveTo(eqX - A * scale, midY - half - 10); ctx.lineTo(eqX - A * scale, midY + half + 4);
ctx.moveTo(eqX + A * scale, midY - half - 10); ctx.lineTo(eqX + A * scale, midY + half + 4);
ctx.stroke();
ctx.setLineDash([]);

ctx.fillStyle = C.faint;
ctx.textAlign = "center";
ctx.fillText("x = 0", eqX, midY - half - 22);
ctx.fillText("-A", eqX - A * scale, midY - half - 14);
ctx.fillText("+A", eqX + A * scale, midY - half - 14);

// mass
ctx.fillStyle = C.figure;
ctx.fillRect(massX - half, midY - half, 2 * half, 2 * half);

// velocity arrow
if (Math.abs(v) > 0.01 * A * w + 1e-6) {
