ctx.fillRect(bx - 13, shelfY - 20, 26, 18);
ctx.fillStyle = C.ink;
ctx.fillText("book, mass m", bx + 18, shelfY - 8);

// start marker
ctx.fillStyle = C.ink;
ctx.beginPath(); ctx.arc(ax, floorY, 4, 0, Math.PI*2); ctx.fill();
ctx.fillText("start", ax - 12, floorY + 16);

// verdict
ctx.fillStyle = C.ink;
ctx.fillText("gravity does -mgh along either path, so U = mgh is a function of height alone", W*0.06, H*0.96);

out.note = "Change of gravitational potential energy depends only on the change in height.";

ctx.font = "12px ui-sans-serif, system-ui, sans-serif";
var k = p.k, x = p.stretch;
var F = k*x, U = 0.5*k*x*x;

// --- spring picture (top third) ---
var midY = H*0.20, wallX = W*0.08;
var natural = W*0.28;
var pixPerM = W*0.36;
var endX = wallX + natural + x*pixPerM;

ctx.fillStyle = C.faint;
ctx.fillRect(wallX - 7, midY - 26, 7, 52);

ctx.strokeStyle = C.accent;
ctx.lineWidth = 2;
ctx.beginPath();
ctx.moveTo(wallX, midY);
var i;
for (i = 1; i <= 14; i++) {
  var sx = wallX + (endX - 14 - wallX)*i/14;
  var sy = midY + (i % 2 === 0 ? -9 : 9)*(i === 14 ? 0 : 1);
  ctx.lineTo(sx, sy);
}
ctx.lineTo(endX - 14, midY);
ctx.stroke();

ctx.strokeStyle = C.rule;
ctx.setLineDash([3, 4]);
ctx.beginPath(); ctx.moveTo(wallX + natural, midY - 30); ctx.lineTo(wallX + natural, midY + 30); ctx.stroke();
ctx.setLineDash([]);
ctx.fillStyle = C.faint;
ctx.fillText("natural length", wallX + natural - 40, midY - 34);

ctx.fillStyle = C.figure;
ctx.fillRect(endX - 14, midY - 14, 28, 28);
ctx.fillStyle = C.ink;
ctx.fillText("stretch x = " + x.toFixed(2) + " m", endX + 22, midY + 4);

// --- F against x graph (bottom) ---
var L = W*0.12, R = W*0.06, Tp = H*0.42, B = H*0.88;
var xmaxG = 0.60, FmaxG = 260;
function GX(q) { return L + q/xmaxG*(W - L - R); }
function GY(q) { return B - q/FmaxG*(B - Tp); }

ctx.strokeStyle = C.rule;
ctx.lineWidth = 1;
ctx.beginPath(); ctx.moveTo(L, B); ctx.lineTo(W - R, B); ctx.stroke();
ctx.beginPath(); ctx.moveTo(L, B); ctx.lineTo(L, Tp); ctx.stroke();
ctx.fillStyle = C.faint;
ctx.fillText("x (m)", W - R - 34, B + 15);
ctx.fillText("F = kx  (N)", L + 6, Tp + 2);

// shaded triangle = stored energy
var xg = Math.min(x, xmaxG);
var Fg = Math.min(k*xg, FmaxG);
ctx.fillStyle = C.accent;
ctx.globalAlpha = 0.25;
ctx.beginPath();
ctx.moveTo(GX(0), GY(0));
ctx.lineTo(GX(xg), GY(0));
ctx.lineTo(GX(xg), GY(Fg));
ctx.closePath();
ctx.fill();
ctx.globalAlpha = 1;

// the line F = kx
ctx.strokeStyle = C.figure;
ctx.lineWidth = 2;
var xEnd = Math.min(xmaxG, FmaxG/k);
ctx.beginPath();
ctx.moveTo(GX(0), GY(0));
ctx.lineTo(GX(xEnd), GY(k*xEnd));
ctx.stroke();

ctx.strokeStyle = C.accent;
ctx.setLineDash([3, 4]);
ctx.beginPath(); ctx.moveTo(GX(xg), GY(0)); ctx.lineTo(GX(xg), GY(Fg)); ctx.stroke();
ctx.setLineDash([]);

ctx.fillStyle = C.ink;
ctx.fillText("area = stored energy = one half k x squared", GX(0) + 12, GY(0) - (B - Tp)*0.12);
ctx.fillText("F = " + F.toFixed(0) + " N", GX(xg) + 6, GY(Fg) - 6);

out.note = "k = " + k.toFixed(0) + " N/m, x = " + x.toFixed(2) + " m: force " + F.toFixed(1) + " N, stored energy " + U.toFixed(2) + " J";

var P = p.power * 1000, m = p.mass, c = p.drag;
var vTop = Math.sqrt(P / c);
var tau = m / (2 * c);
var Tmax = tau * Math.log(50.0);
var padL = 44, padB = 30, padT = 16, padR = 14;
var plotW = W - padL - padR, plotH = H - padT - padB;
var X = function (s) { return padL + plotW * (s / Tmax); };
var Y = function (v) { return padT + plotH * (1 - v / (vTop * 1.12)); };

ctx.font = "12px ui-sans-serif, system-ui, sans-serif";
ctx.lineWidth = 1;

// axes
ctx.strokeStyle = C.rule;
ctx.beginPath();
ctx.moveTo(padL, padT); ctx.lineTo(padL, padT + plotH); ctx.lineTo(padL + plotW, padT + plotH);
ctx.stroke();

// top-speed asymptote
ctx.strokeStyle = C.faint;
ctx.setLineDash([4, 4]);
ctx.beginPath(); ctx.moveTo(padL, Y(vTop)); ctx.lineTo(padL + plotW, Y(vTop)); ctx.stroke();
ctx.setLineDash([]);
ctx.fillStyle = C.faint;
ctx.fillText("top speed " + vTop.toFixed(1) + " m/s", padL + 6, Y(vTop) - 5);

// the drag-free sqrt curve, for comparison
ctx.strokeStyle = C.rule;
ctx.setLineDash([2, 4]);
ctx.beginPath();
for (var i = 0; i <= 120; i++) {
  var s = Tmax * i / 120;
  var vf = Math.sqrt(2 * P * s / m);
  if (vf > vTop * 1.12) break;
  i === 0 ? ctx.moveTo(X(s), Y(vf)) : ctx.lineTo(X(s), Y(vf));
}
ctx.stroke();
ctx.setLineDash([]);

// real curve with drag
ctx.strokeStyle = C.figure;
ctx.lineWidth = 2;
ctx.beginPath();
for (var j = 0; j <= 160; j++) {
  var s2 = Tmax * j / 160;
  var v2 = vTop * Math.sqrt(1 - Math.exp(-s2 / tau));
  j === 0 ? ctx.moveTo(X(s2), Y(v2)) : ctx.lineTo(X(s2), Y(v2));
}
ctx.stroke();
ctx.lineWidth = 1;

// moving marker
var cyc = Tmax * 1.25;
var now = Math.min(t % cyc, Tmax);
var vNow = vTop * Math.sqrt(1 - Math.exp(-now / tau));
ctx.strokeStyle = C.faint;
ctx.beginPath(); ctx.moveTo(X(now), padT + plotH); ctx.lineTo(X(now), Y(vNow)); ctx.stroke();
ctx.fillStyle = C.accent;
ctx.beginPath(); ctx.arc(X(now), Y(vNow), 5, 0, Math.PI * 2); ctx.fill();

// force arrow: length proportional to net force P/v - c v
var Fnet = vNow > 0.2 ? (P / vNow - c * vNow) : 0;
var Fmax = P / (vTop * 0.08);
var arrow = (plotW * 0.18) * Math.min(1, Fnet / Fmax);
ctx.strokeStyle = C.accent;
ctx.beginPath();
ctx.moveTo(X(now), Y(vNow));
ctx.lineTo(X(now) + arrow, Y(vNow));
ctx.stroke();

// labels
ctx.fillStyle = C.ink;
ctx.fillText("v (m/s)", 4, padT + 10);
ctx.fillText("t (s)", padL + plotW - 26, padT + plotH + 20);
ctx.fillStyle = C.faint;
ctx.fillText("0", padL - 8, padT + plotH + 16);
ctx.fillText(Tmax.toFixed(0), padL + plotW - 10, padT + plotH + 16);
ctx.fillStyle = C.rule;
ctx.fillText("no drag: v = sqrt(2Pt/m)", padL + 6, padT + 12);

out.note = "t = " + now.toFixed(1) + " s, v = " + vNow.toFixed(1) + " m/s ("
  + (100 * vNow / vTop).toFixed(0) + "% of top), driving force P/v = "
  + (vNow > 0.2 ? (P / vNow).toFixed(0) : "huge") + " N";

var th = p.angle * Math.PI / 180;
var v = p.speed, m = p.mass, D = p.drag;
var g = 9.8;
var Fgrav = m * g * Math.sin(th);
var Fdrive = Fgrav + D;
var Pw = Fdrive * v;

ctx.font = "12px ui-sans-serif, system-ui, sans-serif";
ctx.lineWidth = 1.5;

var baseY = H - 26, baseX = 22;
var run = W - 90;
var rise = run * Math.tan(th);
if (rise > H - 70) { run = (H - 70) / Math.tan(th); rise = H - 70; }

// the incline
ctx.strokeStyle = C.rule;
ctx.beginPath();
ctx.moveTo(baseX, baseY);
ctx.lineTo(baseX + run, baseY);
ctx.lineTo(baseX + run, baseY - rise);
ctx.closePath();
ctx.stroke();

// angle label
ctx.fillStyle = C.ink;
ctx.fillText(p.angle.toFixed(0) + " deg", baseX + 16, baseY - 6);

// car sits partway up the slope
var f = 0.55;
var cx = baseX + run * f, cy = baseY - rise * f;
var ux = Math.cos(th), uy = -Math.sin(th);
ctx.fillStyle = C.figure;
ctx.save();
ctx.translate(cx, cy);
ctx.rotate(-th);
ctx.fillRect(-16, -13, 32, 11);
ctx.restore();

function arrow(x0, y0, dx, dy, col, label, lx, ly) {
  ctx.strokeStyle = col;
  ctx.fillStyle = col;
  ctx.beginPath(); ctx.moveTo(x0, y0); ctx.lineTo(x0 + dx, y0 + dy); ctx.stroke();
  var L = Math.sqrt(dx * dx + dy * dy);
  if (L > 1) {
    var hx = dx / L, hy = dy / L;
    ctx.beginPath();
    ctx.moveTo(x0 + dx, y0 + dy);
    ctx.lineTo(x0 + dx - 7 * hx + 4 * hy, y0 + dy - 7 * hy - 4 * hx);
    ctx.lineTo(x0 + dx - 7 * hx - 4 * hy, y0 + dy - 7 * hy + 4 * hx);
    ctx.closePath(); ctx.fill();
  }
  ctx.fillText(label, x0 + dx + lx, y0 + dy + ly);
}

var scale = 52 / Math.max(Fdrive, 1);
var ax = cx + ux * 16, ay = cy - 14 + uy * 16;

arrow(ax, ay, ux * Fdrive * scale, uy * Fdrive * scale, C.accent, "F drive", 4, -4);
arrow(cx - ux * 16, cy - 14 - uy * 16, -ux * D * scale, -uy * D * scale, C.figure, "drag", -34, 14);
arrow(cx, cy - 8, 0, m * g * Math.sin(th) * scale * 0.6, C.ink, "", 0, 0);
ctx.fillStyle = C.ink;
ctx.fillText("mg", cx + 5, cy - 8 + m * g * Math.sin(th) * scale * 0.6);

