ctx.globalAlpha = 1;
ctx.strokeStyle = C.figure;
ctx.strokeRect(tankX + tankW * 0.30, top, tankW * 0.16, d * sy);

var cx = tankX + tankW * 0.38;
// weight arrow of the column
