ctx.beginPath();
ctx.moveTo(cx, top + d * sy * 0.35);
ctx.lineTo(cx, top + d * sy * 0.35 + 22);
ctx.lineTo(cx - 3.5, top + d * sy * 0.35 + 16);
ctx.moveTo(cx, top + d * sy * 0.35 + 22);
ctx.lineTo(cx + 3.5, top + d * sy * 0.35 + 16);
ctx.stroke();
ctx.fillStyle = C.ink;
ctx.fillText("weight of column", cx + 8, top + d * sy * 0.35 + 12);

ctx.fillStyle = C.accent;
ctx.beginPath();
ctx.arc(cx, dy, 4, 0, Math.PI * 2);
ctx.fill();
ctx.fillText("depth h = " + d.toFixed(1) + " m", tankX + 6, dy + 14);

// graph of pressure vs depth on the right
var gx0 = tankX + tankW + 46, gx1 = W - 14;
ctx.strokeStyle = C.rule;
ctx.lineWidth = 1;
ctx.beginPath();
ctx.moveTo(gx0, top);
ctx.lineTo(gx0, floorY);
ctx.lineTo(gx1, floorY);
ctx.stroke();

var pAtm = 101000;
var pMax = pAtm + p.rho * 9.8 * depthMax;
var gw = gx1 - gx0;
ctx.strokeStyle = C.figure;
ctx.lineWidth = 2;
ctx.beginPath();
for (var k = 0; k <= 60; k++) {
  var hh = depthMax * k / 60;
  var pp = pAtm + p.rho * 9.8 * hh;
  var X = gx0 + gw * pp / pMax;
  var Y = top + hh * sy;
  k === 0 ? ctx.moveTo(X, Y) : ctx.lineTo(X, Y);
}
ctx.stroke();

var pAbs = pAtm + p.rho * 9.8 * d;
var mx = gx0 + gw * pAbs / pMax;
ctx.fillStyle = C.accent;
ctx.beginPath();
ctx.arc(mx, dy, 4, 0, Math.PI * 2);
ctx.fill();
ctx.strokeStyle = C.accent;
ctx.setLineDash([3, 3]);
ctx.beginPath();
ctx.moveTo(gx0, dy);
ctx.lineTo(mx, dy);
ctx.stroke();
ctx.setLineDash([]);

ctx.fillStyle = C.faint;
ctx.fillText("pressure", gx0 + 4, floorY + 12);
ctx.save();
ctx.translate(gx0 - 12, (top + floorY) / 2);
ctx.rotate(-Math.PI / 2);
ctx.textAlign = "center";
ctx.fillText("depth", 0, 0);
ctx.restore();
ctx.textAlign = "left";

out.note = "gauge " + (p.rho * 9.8 * d / 1000).toFixed(1) + " kPa, absolute " +
  (pAbs / 1000).toFixed(1) + " kPa (" + (pAbs / pAtm).toFixed(2) + " atmospheres)";

ctx.font = "12px ui-sans-serif, system-ui, sans-serif";
ctx.textBaseline = "middle";

var cx = W * 0.40;
var top = H * 0.28, bot = H * 0.74;
var bw = Math.min(W * 0.26, 150);
var left = cx - bw / 2, right = cx + bw / 2;

// water surface
ctx.strokeStyle = C.figure;
ctx.lineWidth = 1.5;
ctx.beginPath();
for (var i = 0; i <= 60; i++) {
  var x = W * i / 60;
  ctx.lineTo(x, 18 + 1.5 * Math.sin(i * 0.4));
}
ctx.stroke();
ctx.fillStyle = C.faint;
ctx.fillText("water surface", 8, 30);

// block
ctx.strokeStyle = C.ink;
ctx.lineWidth = 1.5;
ctx.strokeRect(left, top, bw, bot - top);
ctx.fillStyle = C.ink;
ctx.textAlign = "center";
ctx.fillText("block", cx, (top + bot) / 2);
ctx.textAlign = "left";

function arrow(x0, y0, x1, y1) {
  var a = Math.atan2(y1 - y0, x1 - x0);
  ctx.beginPath();
  ctx.moveTo(x0, y0);
  ctx.lineTo(x1, y1);
  ctx.lineTo(x1 - 5 * Math.cos(a - 0.4), y1 - 5 * Math.sin(a - 0.4));
  ctx.moveTo(x1, y1);
  ctx.lineTo(x1 - 5 * Math.cos(a + 0.4), y1 - 5 * Math.sin(a + 0.4));
  ctx.stroke();
}

// short arrows pushing down on the top face
ctx.strokeStyle = C.figure;
ctx.lineWidth = 1.4;
for (var j = 0; j < 4; j++) {
  var x = left + bw * (j + 0.5) / 4;
  arrow(x, top - 20, x, top - 2);
}
ctx.fillStyle = C.figure;
ctx.fillText("small push down: p at the top face", right + 10, top - 12);

// long arrows pushing up on the bottom face
ctx.strokeStyle = C.accent;
ctx.lineWidth = 1.4;
for (var j2 = 0; j2 < 4; j2++) {
  var x2 = left + bw * (j2 + 0.5) / 4;
  arrow(x2, bot + 34, x2, bot + 2);
}
ctx.fillStyle = C.accent;
ctx.fillText("bigger push up: p is larger deeper down", right + 10, bot + 18);

// sideways arrows cancel
ctx.strokeStyle = C.rule;
ctx.lineWidth = 1.2;
for (var k = 0; k < 3; k++) {
  var y = top + (bot - top) * (k + 0.5) / 3;
  arrow(left - 22, y, left - 3, y);
  arrow(right + 22, y, right + 3, y);
}
ctx.fillStyle = C.faint;
ctx.textAlign = "center";
ctx.fillText("sides cancel", cx, bot + 44);
ctx.textAlign = "left";

// net buoyant force
ctx.strokeStyle = C.accent;
ctx.lineWidth = 2.2;
arrow(W * 0.83, (top + bot) / 2 + 34, W * 0.83, (top + bot) / 2 - 34);
ctx.fillStyle = C.accent;
ctx.textAlign = "center";
ctx.fillText("net = buoyant force", W * 0.83, (top + bot) / 2 - 46);
ctx.fillText("= weight of displaced water", W * 0.83, (top + bot) / 2 + 48);
ctx.textAlign = "left";

ctx.font = "12px ui-sans-serif, system-ui, sans-serif";
ctx.textBaseline = "middle";

var surf = H * 0.36;
var ratio = p.rhoObj / p.rhoFluid;
var floats = ratio < 1;
var frac = floats ? ratio : 1;

var bw = Math.min(W * 0.22, 120);
var bh = H * 0.30;
var cx = W * 0.42;

// water body
ctx.fillStyle = C.faint;
ctx.globalAlpha = 0.18;
ctx.fillRect(0, surf, W, H - surf - 14);
ctx.globalAlpha = 1;
ctx.strokeStyle = C.rule;
ctx.lineWidth = 1.5;
ctx.beginPath();
ctx.moveTo(0, H - 14);
ctx.lineTo(W, H - 14);
ctx.stroke();

// equilibrium position: top of block sits (1-frac)*bh above the surface
var yEqTop = surf - (1 - frac) * bh;

// bobbing: only if it floats, small damped-free oscillation about equilibrium
var amp = floats ? Math.min(bh * 0.18, 16) : 0;
var omega = floats ? Math.sqrt(9.8 / Math.max(ratio * bh / 40, 0.05)) : 0;
var bobPix = amp * Math.cos(t * (floats ? 2.2 + 2.0 * (1 - ratio) : 0));
var sinkPix = floats ? 0 : Math.min((H - 26 - bh - surf), 26 + 14 * Math.sin(t));
var yTop = yEqTop + bobPix + sinkPix;

// wavy surface line
ctx.strokeStyle = C.figure;
ctx.lineWidth = 1.5;
ctx.beginPath();
for (var i = 0; i <= 60; i++) {
  var x = W * i / 60;
  ctx.lineTo(x, surf + 1.6 * Math.sin(i * 0.45 + t * 1.4));
}
ctx.stroke();

// block
ctx.strokeStyle = C.ink;
ctx.lineWidth = 1.6;
ctx.strokeRect(cx - bw / 2, yTop, bw, bh);
// shade submerged part
var subTop = Math.max(yTop, surf);
var subH = Math.max(0, yTop + bh - subTop);
ctx.fillStyle = C.accent;
ctx.globalAlpha = 0.22;
ctx.fillRect(cx - bw / 2, subTop, bw, subH);
ctx.globalAlpha = 1;

ctx.fillStyle = C.ink;
ctx.textAlign = "center";
ctx.fillText("rho = " + p.rhoObj.toFixed(0), cx, yTop + bh / 2);
ctx.textAlign = "left";

function arrow(x0, y0, x1, y1) {
  var a = Math.atan2(y1 - y0, x1 - x0);
  ctx.beginPath();
  ctx.moveTo(x0, y0);
  ctx.lineTo(x1, y1);
  ctx.lineTo(x1 - 6 * Math.cos(a - 0.4), y1 - 6 * Math.sin(a - 0.4));
  ctx.moveTo(x1, y1);
  ctx.lineTo(x1 - 6 * Math.cos(a + 0.4), y1 - 6 * Math.sin(a + 0.4));
  ctx.stroke();
}

// force arrows, scaled to the ratio of buoyancy to weight
var wLen = 46;
var bLen = wLen * (floats ? 1 : p.rhoFluid / p.rhoObj);
var ax = cx + bw / 2 + 34;
ctx.strokeStyle = C.accent;
ctx.lineWidth = 2;
arrow(ax, yTop + bh / 2, ax, yTop + bh / 2 - bLen);
ctx.fillStyle = C.accent;
ctx.fillText("buoyant force", ax + 8, yTop + bh / 2 - bLen);

ctx.strokeStyle = C.ink;
arrow(ax, yTop + bh / 2, ax, yTop + bh / 2 + wLen);
ctx.fillStyle = C.ink;
ctx.fillText("weight", ax + 8, yTop + bh / 2 + wLen);

ctx.fillStyle = C.faint;
ctx.fillText("fluid rho = " + p.rhoFluid.toFixed(0) + " kg/m3", 10, surf + 20);

if (floats) {
  out.note = "floats with " + (frac * 100).toFixed(1) + "% of its volume under water" +
    " (V_sub / V = " + ratio.toFixed(3) + ")";
} else {
  out.note = "sinks: buoyancy is only " + (100 * p.rhoFluid / p.rhoObj).toFixed(1) +
    "% of the weight, apparent weight is " + (100 * (1 - p.rhoFluid / p.rhoObj)).toFixed(1) + "% of the real one";
}

ctx.font = "12px ui-sans-serif, system-ui, sans-serif";
ctx.textBaseline = "middle";

var scale = (H - 60) / 0.9;   // pixels per metre of liquid
var bottomY = H - 26;
var tubeW = Math.min(W * 0.13, 52);
var gapW = Math.min(W * 0.22, 110);
var midX = W * 0.45;
var lx = midX - gapW / 2 - tubeW, rx = midX + gapW / 2;

var hOil = p.hOil;
var rhoOil = p.rhoOil;
var rhoW = 1000;
// water in right arm stands above the interface by rhoOil*hOil/rhoW
var rise = rhoOil * hOil / rhoW;

var interfaceY = bottomY - 0.22 * scale;      // interface in the left arm
var oilTopY = interfaceY - hOil * scale;
var rightY = interfaceY - rise * scale;

// tube outline
ctx.strokeStyle = C.rule;
ctx.lineWidth = 1.5;
ctx.beginPath();
ctx.moveTo(lx, 20); ctx.lineTo(lx, bottomY); ctx.lineTo(rx + tubeW, bottomY); ctx.lineTo(rx + tubeW, 20);
ctx.moveTo(lx + tubeW, 20); ctx.lineTo(lx + tubeW, bottomY - 16); ctx.lineTo(rx, bottomY - 16); ctx.lineTo(rx, 20);
ctx.stroke();

// water fill
ctx.fillStyle = C.accent;
ctx.globalAlpha = 0.20;
ctx.fillRect(lx + 1, interfaceY, tubeW - 2, bottomY - interfaceY - 1);
ctx.fillRect(rx + 1, rightY, tubeW - 2, bottomY - rightY - 1);
ctx.fillRect(lx + tubeW, bottomY - 16, rx - lx - tubeW, 15);
ctx.globalAlpha = 1;

// oil fill
ctx.fillStyle = C.figure;
ctx.globalAlpha = 0.35;
ctx.fillRect(lx + 1, oilTopY, tubeW - 2, hOil * scale);
ctx.globalAlpha = 1;

// level lines
ctx.strokeStyle = C.ink;
ctx.lineWidth = 1.4;
ctx.beginPath(); ctx.moveTo(lx, interfaceY); ctx.lineTo(lx + tubeW, interfaceY); ctx.stroke();
ctx.beginPath(); ctx.moveTo(lx, oilTopY); ctx.lineTo(lx + tubeW, oilTopY); ctx.stroke();
ctx.beginPath(); ctx.moveTo(rx, rightY); ctx.lineTo(rx + tubeW, rightY); ctx.stroke();

// the matching-level line through the interface
ctx.strokeStyle = C.accent;
ctx.setLineDash([4, 4]);
ctx.beginPath(); ctx.moveTo(lx, interfaceY); ctx.lineTo(rx + tubeW + 6, interfaceY); ctx.stroke();
ctx.setLineDash([]);

ctx.fillStyle = C.accent;
ctx.fillText("same level, same pressure", lx - 4, interfaceY + 14);

ctx.fillStyle = C.figure;
ctx.fillText("oil", lx + tubeW / 2 - 8, (oilTopY + interfaceY) / 2);
ctx.fillStyle = C.ink;
ctx.fillText("water", rx + tubeW + 6, (rightY + bottomY) / 2);

// height annotations
function dim(x, y0, y1, label) {
  ctx.strokeStyle = C.faint;
  ctx.lineWidth = 1;
  ctx.beginPath(); ctx.moveTo(x, y0); ctx.lineTo(x, y1); ctx.stroke();
  ctx.beginPath(); ctx.moveTo(x - 4, y0); ctx.lineTo(x + 4, y0);
  ctx.moveTo(x - 4, y1); ctx.lineTo(x + 4, y1); ctx.stroke();
  ctx.fillStyle = C.faint;
  ctx.fillText(label, x + 6, (y0 + y1) / 2);
}
dim(lx - 16, oilTopY, interfaceY, hOil.toFixed(2) + " m oil");
dim(rx + tubeW + 40, rightY, interfaceY, rise.toFixed(3) + " m");

out.note = "rho_oil h_oil = rho_water h_water, so the water stands " +
  rise.toFixed(3) + " m above the interface";

const th = p.angle * Math.PI / 180;
const m = p.mass, g = 9.8;
const a = g * Math.sin(th);
const N = m * g * Math.cos(th);

const pad = 26;
const baseY = H - pad;
const baseX = pad;
const len = (W - pad * 2) * 0.78;
const topY = baseY - len * Math.tan(th);

// incline
ctx.lineWidth = 1.5;
ctx.strokeStyle = C.rule;
ctx.beginPath();
ctx.moveTo(baseX, baseY);
ctx.lineTo(baseX + len, baseY);
ctx.lineTo(baseX + len, topY);
ctx.closePath();
ctx.stroke();

// angle label at the bottom-left corner
ctx.strokeStyle = C.faint;
ctx.beginPath();
ctx.arc(baseX, baseY, 26, -th, 0);
ctx.stroke();
ctx.fillStyle = C.ink;
ctx.font = "12px ui-sans-serif, system-ui, sans-serif";
ctx.fillText("theta = " + p.angle.toFixed(0) + " deg", baseX + 30, baseY - 6);

// block slides from the top, restarts
const sMax = len / Math.cos(th) * 0.72;
const tRun = Math.sqrt(2 * sMax / Math.max(a, 0.001));
const now = (t % (tRun + 0.8));
const s = Math.min(0.5 * a * now * now, sMax);
const startX = baseX + len - sMax * Math.cos(th);
const startY = topY + sMax * Math.sin(th);
const bx = startX + s * Math.cos(th);
const by = startY - s * Math.sin(th);

// block drawn as a small square sitting on the surface
const bs = 16;
ctx.save();
ctx.translate(bx, by);
ctx.rotate(-th);
ctx.fillStyle = C.accent;
ctx.fillRect(-bs / 2, -bs, bs, bs);
ctx.restore();

function arrow(x0, y0, x1, y1, col, label) {
  ctx.strokeStyle = col;
  ctx.fillStyle = col;
  ctx.lineWidth = 1.6;
  ctx.beginPath();
  ctx.moveTo(x0, y0);
  ctx.lineTo(x1, y1);
  ctx.stroke();
  const ang = Math.atan2(y1 - y0, x1 - x0);
  ctx.beginPath();
  ctx.moveTo(x1, y1);
  ctx.lineTo(x1 - 7 * Math.cos(ang - 0.4), y1 - 7 * Math.sin(ang - 0.4));
  ctx.lineTo(x1 - 7 * Math.cos(ang + 0.4), y1 - 7 * Math.sin(ang + 0.4));
  ctx.closePath();
  ctx.fill();
  ctx.font = "12px ui-sans-serif, system-ui, sans-serif";
  ctx.fillText(label, x1 + 4, y1 - 2);
}

// centre of the block, lifted half a block along the surface normal
const cx = bx - (bs / 2) * Math.sin(th);
const cy = by - (bs / 2) * Math.cos(th);
const k = 3.2;

// weight, straight down
arrow(cx, cy, cx, cy + m * g * k * 0.55, C.figure, "mg");
// component along the surface (down-slope)
arrow(cx, cy, cx + m * g * Math.sin(th) * k * Math.cos(th) * 0.55,
      cy + m * g * Math.sin(th) * k * Math.sin(th) * 0.55, C.accent, "mg sin");
// component into the surface
arrow(cx, cy, cx - m * g * Math.cos(th) * k * Math.sin(th) * 0.55,
      cy + m * g * Math.cos(th) * k * Math.cos(th) * 0.55, C.accent, "mg cos");
// normal force, out of the surface
arrow(cx, cy, cx - N * k * Math.sin(th) * 0.55, cy - N * k * Math.cos(th) * 0.55,
      C.ink, "N");

// tilted axis hint
ctx.strokeStyle = C.faint;
ctx.setLineDash([3, 4]);
ctx.beginPath();
ctx.moveTo(cx - 40 * Math.cos(th), cy + 40 * Math.sin(th));
ctx.lineTo(cx + 40 * Math.cos(th), cy - 40 * Math.sin(th));
ctx.stroke();
ctx.setLineDash([]);
ctx.fillStyle = C.faint;
ctx.font = "11px ui-sans-serif, system-ui, sans-serif";
ctx.fillText("x along surface", pad, pad + 2);
ctx.fillText("y perpendicular", pad, pad + 16);

out.note = "a = g sin(theta) = " + a.toFixed(2) + " m/s^2   |   N = mg cos(theta) = " + N.toFixed(1) + " N   |   weight mg = " + (m * g).toFixed(1) + " N";

ctx.lineWidth = 1.6;
ctx.font = "12px ui-sans-serif, system-ui, sans-serif";

function arrow(x0, y0, x1, y1, col, label, above) {
  ctx.strokeStyle = col;
  ctx.fillStyle = col;
  ctx.lineWidth = 1.6;
  ctx.beginPath();
  ctx.moveTo(x0, y0);
  ctx.lineTo(x1, y1);
  ctx.stroke();
  const ang = Math.atan2(y1 - y0, x1 - x0);
  ctx.beginPath();
  ctx.moveTo(x1, y1);
  ctx.lineTo(x1 - 7 * Math.cos(ang - 0.4), y1 - 7 * Math.sin(ang - 0.4));
  ctx.lineTo(x1 - 7 * Math.cos(ang + 0.4), y1 - 7 * Math.sin(ang + 0.4));
  ctx.closePath();
  ctx.fill();
  ctx.font = "12px ui-sans-serif, system-ui, sans-serif";
  ctx.fillText(label, (x0 + x1) / 2 - 10, above ? Math.min(y0, y1) - 6 : Math.max(y0, y1) + 14);
}

const halfW = W / 2;
const groundY = H * 0.62;

// ---- left panel: the pair as one system ----
ctx.strokeStyle = C.faint;
ctx.beginPath();
ctx.moveTo(W * 0.04, groundY);
ctx.lineTo(halfW - W * 0.03, groundY);
ctx.stroke();

const aW = W * 0.10, bW = W * 0.13, bh = H * 0.20;
const ax0 = W * 0.16;
ctx.strokeStyle = C.rule;
ctx.fillStyle = C.paper;
ctx.fillRect(ax0, groundY - bh, aW, bh);
ctx.strokeRect(ax0, groundY - bh, aW, bh);
ctx.fillRect(ax0 + aW, groundY - bh, bW, bh);
ctx.strokeRect(ax0 + aW, groundY - bh, bW, bh);
ctx.fillStyle = C.ink;
ctx.fillText("3 kg", ax0 + 4, groundY - bh / 2);
ctx.fillText("5 kg", ax0 + aW + 6, groundY - bh / 2);

// dashed system boundary around both
ctx.strokeStyle = C.accent;
ctx.setLineDash([5, 4]);
ctx.strokeRect(ax0 - 9, groundY - bh - 9, aW + bW + 18, bh + 18);
ctx.setLineDash([]);

arrow(ax0 - 48, groundY - bh / 2, ax0 - 11, groundY - bh / 2, C.figure, "F = 12 N", true);
ctx.fillStyle = C.accent;
ctx.fillText("system: both blocks", W * 0.05, H * 0.14);
ctx.fillStyle = C.ink;
ctx.fillText("contact force is internal", W * 0.05, H * 0.14 + 16);
ctx.fillText("a = F / (3 + 5) = 1.5 m/s^2", W * 0.05, H * 0.14 + 32);

// divider
ctx.strokeStyle = C.faint;
ctx.beginPath();
ctx.moveTo(halfW, H * 0.06);
ctx.lineTo(halfW, H * 0.94);
ctx.stroke();

// ---- right panel: cut the system, isolate the front block ----
ctx.strokeStyle = C.faint;
ctx.beginPath();
ctx.moveTo(halfW + W * 0.04, groundY);
ctx.lineTo(W * 0.96, groundY);
ctx.stroke();

const cx0 = halfW + W * 0.22;
ctx.strokeStyle = C.rule;
ctx.fillStyle = C.paper;
ctx.fillRect(cx0, groundY - bh, aW, bh);
ctx.strokeRect(cx0, groundY - bh, aW, bh);
ctx.fillStyle = C.ink;
ctx.fillText("3 kg", cx0 + 4, groundY - bh / 2);

ctx.strokeStyle = C.accent;
ctx.setLineDash([5, 4]);
ctx.strokeRect(cx0 - 9, groundY - bh - 9, aW + 18, bh + 18);
ctx.setLineDash([]);

arrow(cx0 - 48, groundY - bh / 2, cx0 - 11, groundY - bh / 2, C.figure, "F = 12 N", true);
arrow(cx0 + aW + 48, groundY - bh / 2, cx0 + aW + 11, groundY - bh / 2, C.figure, "C = 7.5 N", true);
arrow(cx0 + aW / 2, groundY - bh - 12, cx0 + aW / 2, groundY - bh - 44, C.ink, "N", false);
arrow(cx0 + aW / 2, groundY - bh / 2, cx0 + aW / 2, groundY + 26, C.ink, "mg", false);

ctx.fillStyle = C.accent;
ctx.fillText("system: front block only", halfW + W * 0.04, H * 0.14);
ctx.fillStyle = C.ink;
ctx.fillText("contact force is now external", halfW + W * 0.04, H * 0.14 + 16);
ctx.fillText("12 - C = 3 x 1.5, so C = 7.5 N", halfW + W * 0.04, H * 0.14 + 32);

const g = 9.8;
const m1 = p.m1, m2 = p.m2;
const a = (m1 - m2) * g / (m1 + m2);
const T = 2 * m1 * m2 * g / (m1 + m2);

const pad = 26;
const panelW = W * 0.44;

// ---- left: the machine, animated ----
const pulX = panelW * 0.5, pulY = pad + 8, R = 14;
ctx.strokeStyle = C.rule;
ctx.lineWidth = 1.5;
ctx.beginPath();
ctx.arc(pulX, pulY, R, 0, Math.PI * 2);
ctx.stroke();

const span = H - pulY - pad - 30;
const cycle = 1.6;
const ph = ((t % (2 * cycle)) / cycle);
const frac = ph < 1 ? ph : 2 - ph;
const dir = a >= 0 ? 1 : -1;
const shift = dir * (frac - 0.5) * span * 0.35 * Math.min(1, Math.abs(a) / g);

const y1 = pulY + span * 0.45 + shift;
const y2 = pulY + span * 0.45 - shift;

ctx.strokeStyle = C.rule;
ctx.beginPath();
ctx.moveTo(pulX - R, pulY);
ctx.lineTo(pulX - R, y1);
ctx.moveTo(pulX + R, pulY);
ctx.lineTo(pulX + R, y2);
ctx.stroke();

ctx.font = "12px ui-sans-serif, system-ui, sans-serif";
const bw = 30, bh = 20;
ctx.fillStyle = C.accent;
ctx.fillRect(pulX - R - bw / 2, y1, bw, bh);
ctx.fillRect(pulX + R - bw / 2, y2, bw, bh);
ctx.fillStyle = C.ink;
ctx.fillText("m1 = " + m1.toFixed(1) + " kg", pulX - R - bw / 2 - 6, y1 + bh + 16);
ctx.fillText("m2 = " + m2.toFixed(1) + " kg", pulX + R - bw / 2 - 6, y2 + bh + 16);
ctx.fillStyle = C.figure;
ctx.fillText("T = " + T.toFixed(1) + " N", pulX - 24, pulY + span * 0.18);

// ---- right: a against m1, with the two limits marked ----
const gx0 = panelW + 40, gx1 = W - pad;
const gy0 = pad + 6, gy1 = H - pad - 14;
