  ctx.fillStyle = C.ink;
  ctx.textAlign = "center";
  ctx.fillText(title, x0 + pw / 2, 20);
  ctx.fillStyle = C.faint;
  ctx.fillText(sub, x0 + pw / 2, H - 12);
