var tir = s2 > 1;
var th2 = tir ? 0 : Math.asin(s2);
var tx = bx + L * Math.sin(th2), ty = by + L * Math.cos(th2);
if (!tir) {
  arrow(bx, by, tx, ty, C.accent);
  ctx.fillStyle = C.accent;
  ctx.fillText("refracted", tx - 20, ty + 13);
}

ctx.strokeStyle = C.faint;
ctx.beginPath(); ctx.arc(bx, by, 30, -Math.PI / 2 - th1, -Math.PI / 2); ctx.stroke();
ctx.fillStyle = C.ink;
ctx.fillText("t1", bx - 20 - 14 * Math.sin(th1 / 2), by - 30 * Math.cos(th1 / 2) - 4);
if (!tir) {
  ctx.strokeStyle = C.faint;
  ctx.beginPath(); ctx.arc(bx, by, 30, Math.PI / 2 - th2, Math.PI / 2); ctx.stroke();
  ctx.fillStyle = C.ink;
  ctx.fillText("t2", bx + 8 + 16 * Math.sin(th2 / 2), by + 34 * Math.cos(th2 / 2));
}

var u = (t * 0.55) % 2;
var dx, dy;
if (u < 1) { dx = ix + (bx - ix) * u; dy = iy + (by - iy) * u; }
else if (tir) { dx = bx + (rx - bx) * (u - 1); dy = by + (ry - by) * (u - 1); }
else { dx = bx + (tx - bx) * (u - 1); dy = by + (ty - by) * (u - 1); }
ctx.fillStyle = C.ink;
ctx.beginPath(); ctx.arc(dx, dy, 4, 0, Math.PI * 2); ctx.fill();

var note = "angle in = " + p.theta.toFixed(0) + " deg";
if (tir) {
  note += ", no refracted ray: total internal reflection";
} else {
  note += ", angle out = " + (th2 * 180 / Math.PI).toFixed(1) + " deg";
}
if (n1 > n2) {
  note += ", critical angle " + (Math.asin(n2 / n1) * 180 / Math.PI).toFixed(1) + " deg";
}
out.note = note;

var A = p.apex * Math.PI / 180;
var n = p.n;
var th1 = p.inc * Math.PI / 180;
var ha = A / 2;
ctx.font = "12px ui-sans-serif, system-ui, sans-serif";

function arrow(x0, y0, x1, y1, col) {
  ctx.strokeStyle = col; ctx.lineWidth = 2;
  ctx.beginPath(); ctx.moveTo(x0, y0); ctx.lineTo(x1, y1); ctx.stroke();
  var a = Math.atan2(y1 - y0, x1 - x0), s = 7;
  ctx.beginPath();
  ctx.moveTo(x1, y1);
  ctx.lineTo(x1 - s * Math.cos(a - 0.4), y1 - s * Math.sin(a - 0.4));
  ctx.lineTo(x1 - s * Math.cos(a + 0.4), y1 - s * Math.sin(a + 0.4));
  ctx.closePath(); ctx.fillStyle = col; ctx.fill();
  ctx.lineWidth = 1;
}

var side = Math.min(H * 0.66, W * 0.36 / Math.max(0.2, Math.sin(ha)));
var apx = W * 0.52, apy = H * 0.15;
var lf = [-Math.sin(ha), Math.cos(ha)];
var rf = [Math.sin(ha), Math.cos(ha)];
var lb = [apx + lf[0] * side, apy + lf[1] * side];
var rb = [apx + rf[0] * side, apy + rf[1] * side];

ctx.globalAlpha = 0.16;
ctx.fillStyle = C.figure;
ctx.beginPath();
ctx.moveTo(apx, apy); ctx.lineTo(lb[0], lb[1]); ctx.lineTo(rb[0], rb[1]);
ctx.closePath(); ctx.fill();
ctx.globalAlpha = 1;
ctx.strokeStyle = C.rule; ctx.lineWidth = 1.5;
ctx.beginPath();
ctx.moveTo(apx, apy); ctx.lineTo(lb[0], lb[1]); ctx.lineTo(rb[0], rb[1]);
ctx.closePath(); ctx.stroke();
ctx.lineWidth = 1;

var nin = [Math.cos(ha), Math.sin(ha)];
var P = [apx + lf[0] * side * 0.5, apy + lf[1] * side * 0.5];

ctx.setLineDash([3, 4]);
ctx.strokeStyle = C.faint;
ctx.beginPath();
ctx.moveTo(P[0] - nin[0] * 46, P[1] - nin[1] * 46);
ctx.lineTo(P[0] + nin[0] * 46, P[1] + nin[1] * 46);
ctx.stroke();
ctx.setLineDash([]);

var s2 = Math.sin(th1) / n;
var th2 = Math.asin(s2);
var d2 = [nin[0] * Math.cos(th2) - lf[0] * Math.sin(th2),
          nin[1] * Math.cos(th2) - lf[1] * Math.sin(th2)];
var d1 = [nin[0] * Math.cos(th1) - lf[0] * Math.sin(th1),
          nin[1] * Math.cos(th1) - lf[1] * Math.sin(th1)];

arrow(P[0] - d1[0] * side * 0.62, P[1] - d1[1] * side * 0.62, P[0], P[1], C.accent);

var nr = [Math.cos(ha), -Math.sin(ha)];
var den = d2[0] * nr[0] + d2[1] * nr[1];
var num = (apx - P[0]) * nr[0] + (apy - P[1]) * nr[1];
var s = den > 1e-6 ? num / den : 1e9;
var hitsFace = s > 0 && s < 1e8;
var Q = [P[0] + d2[0] * s, P[1] + d2[1] * s];
var alongQ = (Q[0] - apx) * rf[0] + (Q[1] - apy) * rf[1];

if (hitsFace && alongQ > 0 && alongQ < side) {
  ctx.strokeStyle = C.accent; ctx.lineWidth = 2;
  ctx.beginPath(); ctx.moveTo(P[0], P[1]); ctx.lineTo(Q[0], Q[1]); ctx.stroke();
  ctx.lineWidth = 1;
  ctx.setLineDash([3, 4]);
  ctx.strokeStyle = C.faint;
  ctx.beginPath();
  ctx.moveTo(Q[0] - nr[0] * 46, Q[1] - nr[1] * 46);
  ctx.lineTo(Q[0] + nr[0] * 46, Q[1] + nr[1] * 46);
  ctx.stroke();
  ctx.setLineDash([]);

  var cth3 = d2[0] * nr[0] + d2[1] * nr[1];
  var th3 = Math.acos(Math.min(1, Math.max(-1, cth3)));
  var sgn = (d2[0] * rf[0] + d2[1] * rf[1]) >= 0 ? 1 : -1;
  var s4 = n * Math.sin(th3);
  if (s4 <= 1) {
    var th4 = Math.asin(s4);
    var d3 = [nr[0] * Math.cos(th4) + rf[0] * sgn * Math.sin(th4),
              nr[1] * Math.cos(th4) + rf[1] * sgn * Math.sin(th4)];
    arrow(Q[0], Q[1], Q[0] + d3[0] * side * 0.55, Q[1] + d3[1] * side * 0.55, C.accent);
    var D = (th1 - th2) + (th4 - th3);
    out.note = "in " + p.inc.toFixed(0) + " deg, out " +
      (th4 * 180 / Math.PI).toFixed(1) + " deg, total deviation " +
      (D * 180 / Math.PI).toFixed(1) + " deg";
  } else {
    var dot = d2[0] * nr[0] + d2[1] * nr[1];
    var dr = [d2[0] - 2 * dot * nr[0], d2[1] - 2 * dot * nr[1]];
    ctx.setLineDash([5, 4]);
    arrow(Q[0], Q[1], Q[0] + dr[0] * side * 0.5, Q[1] + dr[1] * side * 0.5, C.figure);
    ctx.setLineDash([]);
    out.note = "internal angle " + (th3 * 180 / Math.PI).toFixed(1) +
      " deg is past the critical angle " +
      (Math.asin(1 / n) * 180 / Math.PI).toFixed(1) +
      " deg: trapped, nothing emerges";
  }
} else {
  out.note = "the ray misses the second face at this apex angle";
}

ctx.fillStyle = C.ink;
ctx.fillText("apex " + p.apex.toFixed(0) + " deg", apx + 8, apy + 4);
ctx.fillText("n = " + n.toFixed(2), apx - 14, apy + side * 0.72);

var n = p.n;
ctx.font = "12px ui-sans-serif, system-ui, sans-serif";
var thc = Math.asin(1 / n);
var sy = H * 0.30;
var d = Math.min(H * 0.50, W * 0.30 / Math.max(0.35, Math.tan(thc)));
var sx = W * 0.5, syy = sy + d;

ctx.globalAlpha = 0.16;
ctx.fillStyle = C.figure;
ctx.fillRect(0, sy, W, H - sy);
ctx.globalAlpha = 1;
ctx.strokeStyle = C.rule; ctx.lineWidth = 1.5;
ctx.beginPath(); ctx.moveTo(0, sy); ctx.lineTo(W, sy); ctx.stroke();
ctx.lineWidth = 1;

ctx.fillStyle = C.ink;
ctx.fillText("air, n = 1", 8, 15);
ctx.fillText("water, n = " + n.toFixed(2), 8, H - 8);

ctx.setLineDash([3, 4]);
ctx.strokeStyle = C.faint;
ctx.beginPath(); ctx.moveTo(sx, syy); ctx.lineTo(sx, sy - H * 0.22); ctx.stroke();
ctx.setLineDash([]);

var r = d * Math.tan(thc);
var angs = [thc * 0.35, thc * 0.7, thc, thc + 0.18, thc + 0.42];
for (var i = 0; i < angs.length; i++) {
  var a = angs[i];
  var hx = sx + d * Math.tan(a);
  if (hx > W - 4) continue;
  ctx.strokeStyle = C.accent; ctx.lineWidth = 1.6;
  ctx.beginPath(); ctx.moveTo(sx, syy); ctx.lineTo(hx, sy); ctx.stroke();
  var s2 = n * Math.sin(a);
  if (s2 < 1) {
    var b = Math.asin(s2);
    var Lo = (sy - 8) / Math.cos(b) * 0.9;
    ctx.strokeStyle = C.accent;
    ctx.beginPath();
    ctx.moveTo(hx, sy);
    ctx.lineTo(hx + Lo * Math.sin(b), sy - Lo * Math.cos(b));
    ctx.stroke();
  } else {
    ctx.strokeStyle = C.figure; ctx.lineWidth = 1.6;
    ctx.beginPath();
    ctx.moveTo(hx, sy);
    ctx.lineTo(hx + (H - sy) * 0.8 * Math.tan(a), sy + (H - sy) * 0.8);
    ctx.stroke();
  }
  ctx.lineWidth = 1;
}

ctx.fillStyle = C.ink;
ctx.beginPath(); ctx.arc(sx, syy, 4.5, 0, Math.PI * 2); ctx.fill();
ctx.fillText("lamp", sx - 44, syy + 4);

ctx.strokeStyle = C.ink; ctx.lineWidth = 1.5;
ctx.beginPath(); ctx.moveTo(sx, sy - 14); ctx.lineTo(sx + r, sy - 14); ctx.stroke();
ctx.beginPath(); ctx.moveTo(sx + r, sy - 20); ctx.lineTo(sx + r, sy - 8); ctx.stroke();
ctx.beginPath(); ctx.moveTo(sx, sy - 20); ctx.lineTo(sx, sy - 8); ctx.stroke();
ctx.lineWidth = 1;
ctx.fillStyle = C.ink;
ctx.fillText("window radius", sx + 6, sy - 22);

ctx.strokeStyle = C.faint;
ctx.beginPath(); ctx.arc(sx, syy, 34, -Math.PI / 2, -Math.PI / 2 + thc); ctx.stroke();
ctx.fillStyle = C.ink;
ctx.fillText("critical angle", sx + 10, syy - 40);
ctx.fillStyle = C.figure;
ctx.fillText("trapped inside", sx + r + 10, sy + (H - sy) * 0.55);

out.note = "critical angle " + (thc * 180 / Math.PI).toFixed(1) +
  " deg, so a lamp at depth h lights a circle of radius " +
  Math.tan(thc).toFixed(2) + " h";

function arrow(x1, y1, x2, y2, col, wid) {
  ctx.strokeStyle = col; ctx.fillStyle = col; ctx.lineWidth = wid || 2;
  ctx.beginPath(); ctx.moveTo(x1, y1); ctx.lineTo(x2, y2); ctx.stroke();
  var a = Math.atan2(y2 - y1, x2 - x1), h = 8;
  ctx.beginPath();
  ctx.moveTo(x2, y2);
  ctx.lineTo(x2 - h * Math.cos(a - 0.4), y2 - h * Math.sin(a - 0.4));
  ctx.lineTo(x2 - h * Math.cos(a + 0.4), y2 - h * Math.sin(a + 0.4));
  ctx.closePath(); ctx.fill();
}

ctx.font = "12px ui-sans-serif, system-ui, sans-serif";
ctx.lineJoin = "round";

var u = p.boat, v = p.current;
var th = p.heading * Math.PI / 180;

// boat relative to water, in a frame where +x is downstream and +y is across
var bwx = -u * Math.sin(th), bwy = u * Math.cos(th);
var wgx = v, wgy = 0;
var bgx = bwx + wgx, bgy = bwy + wgy;

var big = Math.max(u + v, 1);
var s = Math.min(W * 0.34, H * 0.62) / big;

var ox = W * 0.30, oy = H * 0.86;
function PX(x) { return ox + x * s; }
function PY(y) { return oy - y * s; }

// reference axes
ctx.strokeStyle = C.faint; ctx.lineWidth = 1;
ctx.setLineDash([3, 4]);
ctx.beginPath(); ctx.moveTo(20, oy); ctx.lineTo(W - 20, oy); ctx.stroke();
ctx.beginPath(); ctx.moveTo(ox, oy); ctx.lineTo(ox, H * 0.08); ctx.stroke();
ctx.setLineDash([]);
ctx.fillStyle = C.faint;
ctx.fillText("straight across", ox + 6, H * 0.10);
ctx.fillText("downstream", W - 96, oy + 16);

// v(boat / water)
arrow(PX(0), PY(0), PX(bwx), PY(bwy), C.accent, 2.4);
// v(water / ground), laid tail-to-head on the first
arrow(PX(bwx), PY(bwy), PX(bgx), PY(bgy), C.figure, 2.4);
// resultant v(boat / ground)
arrow(PX(0), PY(0), PX(bgx), PY(bgy), C.ink, 2.4);

ctx.fillStyle = C.accent;
ctx.fillText("v(boat/water) = " + u.toFixed(1), PX(bwx) - 60, PY(bwy) - 8);
ctx.fillStyle = C.figure;
ctx.fillText("v(water/ground) = " + v.toFixed(1), PX(bwx) + 6, PY(bwy) - 8 + 16);
ctx.fillStyle = C.ink;
var spd = Math.sqrt(bgx * bgx + bgy * bgy);
ctx.fillText("v(boat/ground) = " + spd.toFixed(2), PX(bgx) + 8, PY(bgy) + 4);

// mark the heading angle
ctx.strokeStyle = C.rule; ctx.lineWidth = 1;
ctx.beginPath();
ctx.arc(ox, oy, 26, -Math.PI / 2 - Math.abs(th), -Math.PI / 2);
ctx.stroke();
ctx.fillStyle = C.rule;
ctx.fillText(Math.abs(p.heading).toFixed(0) + " deg", ox - 46, oy - 30);

var drift = bgx;
var msg;
if (Math.abs(drift) < 0.02) {
  msg = "sideways drift cancels exactly: the boat lands directly opposite";
} else if (drift > 0) {
  msg = "net downstream velocity " + drift.toFixed(2) + " m/s";
} else {
  msg = "net upstream velocity " + (-drift).toFixed(2) + " m/s";
}
out.note = "across " + bgy.toFixed(2) + " m/s, " + msg;

function arrow(x1, y1, x2, y2, col, wid) {
  ctx.strokeStyle = col; ctx.fillStyle = col; ctx.lineWidth = wid || 2;
  ctx.beginPath(); ctx.moveTo(x1, y1); ctx.lineTo(x2, y2); ctx.stroke();
  var a = Math.atan2(y2 - y1, x2 - x1), h = 8;
  ctx.beginPath();
  ctx.moveTo(x2, y2);
  ctx.lineTo(x2 - h * Math.cos(a - 0.4), y2 - h * Math.sin(a - 0.4));
  ctx.lineTo(x2 - h * Math.cos(a + 0.4), y2 - h * Math.sin(a + 0.4));
  ctx.closePath(); ctx.fill();
}

ctx.font = "12px ui-sans-serif, system-ui, sans-serif";
ctx.lineJoin = "round";

var u = p.boat, v = p.current, wd = p.width;
var th = p.heading * Math.PI / 180;

var across = u * Math.cos(th);
var along = v - u * Math.sin(th);
var T = wd / across;
var drift = along * T;

var pad = 34;
var lo = Math.min(0, drift), hi = Math.max(0, drift);
var span = Math.max(hi - lo, wd * 0.5);
lo = lo - span * 0.18; hi = hi + span * 0.18;
var sx = (W - pad * 2) / (hi - lo);
var sy = (H - pad * 2) / wd;
function X(x) { return pad + (x - lo) * sx; }
function Y(y) { return H - pad - y * sy; }

// banks
ctx.strokeStyle = C.rule; ctx.lineWidth = 1.5;
ctx.beginPath(); ctx.moveTo(0, Y(0)); ctx.lineTo(W, Y(0)); ctx.stroke();
ctx.beginPath(); ctx.moveTo(0, Y(wd)); ctx.lineTo(W, Y(wd)); ctx.stroke();
ctx.fillStyle = C.faint;
ctx.fillText("far bank", 6, Y(wd) - 6);
ctx.fillText("near bank (start)", 6, Y(0) + 16);

// current arrows
var rows = 4, k, j;
for (k = 1; k <= rows; k++) {
  var yy = wd * k / (rows + 1);
  for (j = 0; j < 3; j++) {
    var x0 = W * (0.14 + 0.30 * j);
    arrow(x0, Y(yy), x0 + 26, Y(yy), C.faint, 1);
  }
}
ctx.fillStyle = C.faint;
ctx.fillText("current " + v.toFixed(1) + " m/s", W * 0.14, Y(wd * 0.5) - 8);

// straight-across reference
ctx.strokeStyle = C.faint; ctx.lineWidth = 1;
ctx.setLineDash([3, 4]);
ctx.beginPath(); ctx.moveTo(X(0), Y(0)); ctx.lineTo(X(0), Y(wd)); ctx.stroke();
ctx.setLineDash([]);

// ground track
ctx.strokeStyle = C.rule; ctx.lineWidth = 1;
ctx.setLineDash([5, 5]);
ctx.beginPath(); ctx.moveTo(X(0), Y(0)); ctx.lineTo(X(drift), Y(wd)); ctx.stroke();
ctx.setLineDash([]);

// animate
var cyc = T * 1.35;
var cur = t % cyc; if (cur > T) cur = T;
var bx = along * cur, by = across * cur;

ctx.strokeStyle = C.accent; ctx.lineWidth = 2.4;
ctx.beginPath(); ctx.moveTo(X(0), Y(0)); ctx.lineTo(X(bx), Y(by)); ctx.stroke();

ctx.fillStyle = C.accent;
ctx.beginPath(); ctx.arc(X(bx), Y(by), 5, 0, Math.PI * 2); ctx.fill();

// where the nose points
var nx = -u * Math.sin(th), ny = u * Math.cos(th);
var nn = Math.sqrt(nx * nx + ny * ny);
arrow(X(bx), Y(by), X(bx) + nx / nn * 30, Y(by) - ny / nn * 30, C.figure, 1.8);
ctx.fillStyle = C.figure;
ctx.fillText("nose", X(bx) + nx / nn * 30 + 4, Y(by) - ny / nn * 30 - 2);

// landing point
ctx.fillStyle = C.ink;
ctx.beginPath(); ctx.arc(X(drift), Y(wd), 3.5, 0, Math.PI * 2); ctx.fill();
ctx.fillText("lands here", X(drift) + 7, Y(wd) + 16);

out.note = "crossing takes " + T.toFixed(1) + " s, lands " +
  Math.abs(drift).toFixed(1) + " m " + (drift >= 0 ? "downstream" : "upstream") +
  " of the start";

function arrow(x1, y1, x2, y2, col, wid) {
  ctx.strokeStyle = col; ctx.fillStyle = col; ctx.lineWidth = wid || 2;
  ctx.beginPath(); ctx.moveTo(x1, y1); ctx.lineTo(x2, y2); ctx.stroke();
  var a = Math.atan2(y2 - y1, x2 - x1), h = 8;
  ctx.beginPath();
  ctx.moveTo(x2, y2);
  ctx.lineTo(x2 - h * Math.cos(a - 0.4), y2 - h * Math.sin(a - 0.4));
  ctx.lineTo(x2 - h * Math.cos(a + 0.4), y2 - h * Math.sin(a + 0.4));
  ctx.closePath(); ctx.fill();
}

ctx.font = "12px ui-sans-serif, system-ui, sans-serif";
ctx.lineJoin = "round";

var va = p.va, vb = p.vb, d = p.d;
var tmin = d * vb / (va * va + vb * vb);
var dmin = d * va / Math.sqrt(va * va + vb * vb);
var Tmax = Math.max(2 * tmin, 0.2);
var cur = t % (Tmax * 1.3); if (cur > Tmax) cur = Tmax;

var pad = 30, gap = 14;
var pw = (W - pad * 2 - gap) / 2;
var ph = H - pad * 2 - 12;

// world box shared by both panels
var xlo = -va * Tmax - d * 0.15, xhi = va * Tmax + d * 0.15;
var ylo = d - vb * Tmax - d * 0.15, yhi = d + d * 0.15;
var s = Math.min(pw / (xhi - xlo), ph / (yhi - ylo));

function mk(left) {
  return {
    X: function (x) { return left + pw / 2 + (x - (xlo + xhi) / 2) * s; },
    Y: function (y) { return pad + 12 + ph / 2 - (y - (ylo + yhi) / 2) * s; }
  };
}
var L = mk(pad), R = mk(pad + pw + gap);

ctx.strokeStyle = C.faint; ctx.lineWidth = 1;
ctx.strokeRect(pad, pad + 12, pw, ph);
ctx.strokeRect(pad + pw + gap, pad + 12, pw, ph);
ctx.fillStyle = C.faint;
ctx.fillText("ground frame", pad + 2, pad + 6);
ctx.fillText("frame of ship A", pad + pw + gap + 2, pad + 6);

// ---- left panel: both ships move
var ax = va * cur, ay = 0;
var bx = 0, by = d - vb * cur;

ctx.strokeStyle = C.rule; ctx.lineWidth = 1;
ctx.setLineDash([4, 4]);
ctx.beginPath(); ctx.moveTo(L.X(0), L.Y(0)); ctx.lineTo(L.X(va * Tmax), L.Y(0)); ctx.stroke();
ctx.beginPath(); ctx.moveTo(L.X(0), L.Y(d)); ctx.lineTo(L.X(0), L.Y(d - vb * Tmax)); ctx.stroke();
ctx.setLineDash([]);

ctx.strokeStyle = C.figure; ctx.lineWidth = 1.2;
ctx.beginPath(); ctx.moveTo(L.X(ax), L.Y(ay)); ctx.lineTo(L.X(bx), L.Y(by)); ctx.stroke();

ctx.fillStyle = C.accent;
ctx.beginPath(); ctx.arc(L.X(ax), L.Y(ay), 5, 0, Math.PI * 2); ctx.fill();
ctx.fillText("A", L.X(ax) - 4, L.Y(ay) + 18);
ctx.fillStyle = C.ink;
ctx.beginPath(); ctx.arc(L.X(bx), L.Y(by), 5, 0, Math.PI * 2); ctx.fill();
ctx.fillText("B", L.X(bx) + 8, L.Y(by) + 4);

var sep = Math.sqrt((bx - ax) * (bx - ax) + (by - ay) * (by - ay));
ctx.fillStyle = C.figure;
ctx.fillText(sep.toFixed(1), (L.X(ax) + L.X(bx)) / 2 - 10, (L.Y(ay) + L.Y(by)) / 2 - 5);

// ---- right panel: A pinned, B on a straight line
var rx = -va * cur, ry = d - vb * cur;

ctx.strokeStyle = C.rule; ctx.lineWidth = 1;
ctx.setLineDash([4, 4]);
ctx.beginPath();
ctx.moveTo(R.X(0), R.Y(d));
ctx.lineTo(R.X(-va * Tmax), R.Y(d - vb * Tmax));
ctx.stroke();
ctx.setLineDash([]);

// perpendicular from A to that straight line = closest approach
var ux = -va, uy = -vb, un = Math.sqrt(ux * ux + uy * uy);
ux = ux / un; uy = uy / un;
var proj = (0 - 0) * ux + (0 - d) * uy;
var fx = 0 + proj * ux, fy = d + proj * uy;
ctx.strokeStyle = C.accent; ctx.lineWidth = 1.6;
ctx.beginPath(); ctx.moveTo(R.X(0), R.Y(0)); ctx.lineTo(R.X(fx), R.Y(fy)); ctx.stroke();
ctx.fillStyle = C.accent;
ctx.fillText("min " + dmin.toFixed(2), R.X(fx) - 4, R.Y(fy) - 6);

arrow(R.X(rx), R.Y(ry), R.X(rx + ux * d * 0.35), R.Y(ry + uy * d * 0.35), C.figure, 1.8);
ctx.fillStyle = C.figure;
