out.note = n + " flip(s): " + cond;

var nTop = 1.0;
var nF = p.nfilm, nS = p.nsub, th = p.thick;
var flipTop = nF > nTop ? 1 : 0;
var flipBot = nS > nF ? 1 : 0;
var net = (flipTop + flipBot) % 2;

var padL = 44, padR = 14, padT = 16, padB = 30;
var gx0 = padL, gx1 = W - padR, gy0 = padT, gy1 = H - padB;
var lam0 = 400, lam1 = 700;
var X = function (lam) { return gx0 + (lam - lam0) / (lam1 - lam0) * (gx1 - gx0); };
var Y = function (v) { return gy1 - v * (gy1 - gy0); };

var refl = function (lam) {
  var delta = 2 * Math.PI * (2 * nF * th) / lam + (net ? Math.PI : 0);
  var c = Math.cos(delta / 2);
  return c * c;
};

ctx.lineWidth = 1;
ctx.strokeStyle = C.faint;
ctx.beginPath();
ctx.moveTo(gx0, gy0); ctx.lineTo(gx0, gy1); ctx.lineTo(gx1, gy1);
ctx.stroke();

ctx.font = "12px ui-sans-serif, system-ui, sans-serif";
ctx.fillStyle = C.ink;
ctx.textAlign = "center";
for (var lam = 400; lam <= 700; lam += 50) {
  ctx.strokeStyle = C.faint;
  ctx.beginPath(); ctx.moveTo(X(lam), gy1); ctx.lineTo(X(lam), gy1 + 4); ctx.stroke();
  ctx.fillText(String(lam), X(lam), gy1 + 17);
}
ctx.fillText("wavelength in vacuum (nm)", (gx0 + gx1) / 2, gy1 + 29);
ctx.textAlign = "right";
ctx.fillText("1", gx0 - 6, gy0 + 5);
ctx.fillText("0", gx0 - 6, gy1 + 4);
ctx.save();
ctx.translate(14, (gy0 + gy1) / 2);
ctx.rotate(-Math.PI / 2);
ctx.textAlign = "center";
ctx.fillText("reflected", 0, 0);
ctx.restore();

ctx.strokeStyle = C.accent;
ctx.lineWidth = 2;
ctx.beginPath();
for (var i = 0; i <= 300; i++) {
  var L = lam0 + (lam1 - lam0) * i / 300;
  var px = X(L), py = Y(refl(L));
  if (i === 0) ctx.moveTo(px, py); else ctx.lineTo(px, py);
}
ctx.stroke();

var scan = lam0 + (lam1 - lam0) * (0.5 - 0.5 * Math.cos(t * 0.7));
ctx.strokeStyle = C.figure;
ctx.lineWidth = 1;
ctx.setLineDash([3, 4]);
ctx.beginPath(); ctx.moveTo(X(scan), gy0); ctx.lineTo(X(scan), gy1); ctx.stroke();
ctx.setLineDash([]);
ctx.fillStyle = C.figure;
ctx.beginPath(); ctx.arc(X(scan), Y(refl(scan)), 4, 0, Math.PI * 2); ctx.fill();

var best = lam0, bestV = -1, dark = 0, darkV = 2;
for (var k = 0; k <= 300; k++) {
  var Lk = lam0 + (lam1 - lam0) * k / 300;
  var v = refl(Lk);
  if (v > bestV) { bestV = v; best = Lk; }
  if (v < darkV) { darkV = v; dark = Lk; }
}
out.note = "flips: " + (flipTop + flipBot) + "  |  2nt = " + (2 * nF * th).toFixed(0) +
  " nm  |  brightest near " + best.toFixed(0) + " nm, weakest near " + dark.toFixed(0) + " nm";

var R = p.radius, lam = p.lambda * 1e-9, ng = p.ngap;
ctx.font = "12px ui-sans-serif, system-ui, sans-serif";

var mMax = 14;
var rMax = Math.sqrt(mMax * lam * R / ng);
var cx = W * 0.5, cy = H * 0.52;
var Rpx = Math.min(W, H) * 0.42;
var S = Rpx / rMax;

ctx.strokeStyle = C.faint;
ctx.lineWidth = 1;
ctx.beginPath(); ctx.arc(cx, cy, Rpx, 0, Math.PI * 2); ctx.stroke();

var highlight = 1 + (Math.floor(t / 1.2) % 6);

for (var m = 1; m <= mMax; m++) {
  var r = Math.sqrt(m * lam * R / ng) * S;
  if (r > Rpx) break;
  ctx.strokeStyle = (m === highlight) ? C.accent : C.ink;
  ctx.lineWidth = (m === highlight) ? 3 : 1.6;
  ctx.beginPath(); ctx.arc(cx, cy, r, 0, Math.PI * 2); ctx.stroke();
}

ctx.fillStyle = C.ink;
ctx.beginPath(); ctx.arc(cx, cy, 3, 0, Math.PI * 2); ctx.fill();
ctx.textAlign = "center";
ctx.fillText("dark centre, m = 0", cx, cy + Rpx + 18);

var rh = Math.sqrt(highlight * lam * R / ng);
var rhpx = rh * S;
ctx.strokeStyle = C.accent;
ctx.lineWidth = 1;
ctx.setLineDash([3, 3]);
ctx.beginPath(); ctx.moveTo(cx, cy); ctx.lineTo(cx + rhpx, cy); ctx.stroke();
ctx.setLineDash([]);
ctx.fillStyle = C.accent;
ctx.textAlign = "left";
ctx.fillText("m = " + highlight, cx + rhpx * 0.35, cy - 6);

ctx.fillStyle = C.ink;
ctx.textAlign = "left";
ctx.fillText("dark rings, 2 n t = m lambda", 6, 14);

out.note = "ring m = " + highlight + " has radius " + (rh * 1000).toFixed(3) +
  " mm  |  gap there t = " + (rh * rh / (2 * R) * 1e9).toFixed(0) + " nm";

var F = p.force, r = p.dist, th = p.angle * Math.PI / 180;
var cx = W * 0.26, cy = H * 0.66;
var len = (r / 0.50) * (W * 0.40);
var ux = Math.cos(th), uy = -Math.sin(th);
var ax = cx + len, ay = cy;

ctx.font = "12px ui-sans-serif, system-ui, sans-serif";
ctx.lineWidth = 2;

// line of action, dashed, extended both ways
ctx.strokeStyle = C.faint;
ctx.setLineDash([4, 4]);
ctx.beginPath();
ctx.moveTo(ax - ux * W, ay - uy * W);
ctx.lineTo(ax + ux * W, ay + uy * W);
ctx.stroke();
ctx.setLineDash([]);

// handle
ctx.strokeStyle = C.ink;
ctx.lineWidth = 5;
ctx.beginPath(); ctx.moveTo(cx, cy); ctx.lineTo(ax, ay); ctx.stroke();
ctx.lineWidth = 2;

// bolt
ctx.fillStyle = C.figure;
ctx.beginPath(); ctx.arc(cx, cy, 9, 0, Math.PI * 2); ctx.fill();
ctx.fillStyle = C.ink;
ctx.fillText("pivot (bolt)", cx - 22, cy + 26);

// r label along handle
ctx.strokeStyle = C.rule;
ctx.beginPath(); ctx.moveTo(cx, cy - 16); ctx.lineTo(ax, ay - 16); ctx.stroke();
ctx.fillStyle = C.ink;
ctx.fillText("r = " + r.toFixed(2) + " m", (cx + ax) / 2 - 26, cy - 22);

// lever arm: foot of perpendicular from pivot onto the line of action
var vx = cx - ax, vy = cy - ay;
var s = vx * ux + vy * uy;
var fx = ax + s * ux, fy = ay + s * uy;
ctx.strokeStyle = C.accent;
ctx.setLineDash([3, 3]);
ctx.beginPath(); ctx.moveTo(cx, cy); ctx.lineTo(fx, fy); ctx.stroke();
ctx.setLineDash([]);
var rperp = Math.abs(r * Math.sin(th));
ctx.fillStyle = C.accent;
ctx.fillText("lever arm " + rperp.toFixed(3) + " m", (cx + fx) / 2 - 40, (cy + fy) / 2 - 8);

// force arrow at the handle end
var alen = (F / 200) * (W * 0.24) + 14;
var ex = ax + ux * alen, ey = ay + uy * alen;
ctx.strokeStyle = C.figure;
ctx.lineWidth = 3;
ctx.beginPath(); ctx.moveTo(ax, ay); ctx.lineTo(ex, ey); ctx.stroke();
ctx.beginPath();
ctx.moveTo(ex, ey);
ctx.lineTo(ex - ux * 11 - uy * 6, ey - uy * 11 + ux * 6);
ctx.lineTo(ex - ux * 11 + uy * 6, ey - uy * 11 - ux * 6);
ctx.closePath();
ctx.fillStyle = C.figure;
ctx.fill();
ctx.fillText("F = " + F.toFixed(0) + " N", ex + 6, ey - 6);

// angle marker at the handle end
ctx.strokeStyle = C.rule;
ctx.lineWidth = 1.5;
ctx.beginPath(); ctx.arc(ax, ay, 26, -th, 0, th > 0); ctx.stroke();
ctx.fillStyle = C.ink;
ctx.fillText(p.angle.toFixed(0) + " deg", ax + 30, ay - 10);

var tau = r * F * Math.sin(th);
ctx.fillStyle = C.ink;
ctx.fillText("torque = r F sin(angle) = lever arm x F", 14, H - 12);
out.note = "tau = " + Math.abs(tau).toFixed(1) + " N·m   (lever arm " + rperp.toFixed(3) + " m x " + F.toFixed(0) + " N)";

var g = 9.8;
var L = 5.0, mp = 30, mper = p.mass, x = p.pos;
var Wp = mp * g, Wper = mper * g;
var NR = (Wp * (L / 2) + Wper * x) / L;
var NL = Wp + Wper - NR;

var x0 = W * 0.12, x1 = W * 0.88, by = H * 0.52;
function px(u) { return x0 + (u / L) * (x1 - x0); }
ctx.font = "12px ui-sans-serif, system-ui, sans-serif";
ctx.lineWidth = 2;

function arrow(sx, sy, ex, ey, col) {
  var dx = ex - sx, dy = ey - sy, m = Math.sqrt(dx * dx + dy * dy);
  var ux = dx / m, uy = dy / m;
  ctx.strokeStyle = col; ctx.fillStyle = col; ctx.lineWidth = 2.5;
  ctx.beginPath(); ctx.moveTo(sx, sy); ctx.lineTo(ex, ey); ctx.stroke();
  ctx.beginPath();
  ctx.moveTo(ex, ey);
  ctx.lineTo(ex - ux * 10 - uy * 5, ey - uy * 10 + ux * 5);
  ctx.lineTo(ex - ux * 10 + uy * 5, ey - uy * 10 - ux * 5);
  ctx.closePath(); ctx.fill();
}

// plank
ctx.fillStyle = C.faint;
ctx.fillRect(x0, by - 7, x1 - x0, 14);
ctx.strokeStyle = C.rule; ctx.lineWidth = 1;
ctx.strokeRect(x0, by - 7, x1 - x0, 14);

// supports as triangles
ctx.fillStyle = C.rule;
var sup = [px(0), px(L)];
for (var i = 0; i < 2; i++) {
  ctx.beginPath();
  ctx.moveTo(sup[i], by + 8);
  ctx.lineTo(sup[i] - 12, by + 28);
  ctx.lineTo(sup[i] + 12, by + 28);
  ctx.closePath(); ctx.fill();
}
ctx.fillStyle = C.ink;
ctx.fillText("A", px(0) - 4, by + 42);
ctx.fillText("B", px(L) - 4, by + 42);

// normal forces up
var sc = (H * 0.30) / 900;
arrow(px(0), by - 8, px(0), by - 8 - NL * sc, C.accent);
arrow(px(L), by - 8, px(L), by - 8 - NR * sc, C.accent);
ctx.fillStyle = C.accent;
ctx.fillText("N_A = " + NL.toFixed(0) + " N", px(0) - 14, by - 16 - NL * sc);
ctx.fillText("N_B = " + NR.toFixed(0) + " N", px(L) - 44, by - 16 - NR * sc);

// plank weight at centre
ctx.fillStyle = C.ink;
ctx.beginPath(); ctx.arc(px(L / 2), by, 4, 0, Math.PI * 2); ctx.fill();
arrow(px(L / 2), by + 8, px(L / 2), by + 8 + Wp * sc, C.figure);
ctx.fillStyle = C.figure;
ctx.fillText("plank " + Wp.toFixed(0) + " N at 2.5 m", px(L / 2) - 50, by + 24 + Wp * sc);

// person weight
arrow(px(x), by + 8, px(x), by + 8 + Wper * sc, C.figure);
ctx.fillText("person " + Wper.toFixed(0) + " N", px(x) - 34, by + 38 + Wper * sc);
ctx.strokeStyle = C.rule; ctx.lineWidth = 1;
ctx.setLineDash([3, 3]);
ctx.beginPath(); ctx.moveTo(px(x), by - 40); ctx.lineTo(px(x), by - 8); ctx.stroke();
ctx.setLineDash([]);
ctx.fillStyle = C.ink;
ctx.fillText("x = " + x.toFixed(2) + " m", px(x) - 26, by - 46);

out.note = "N_A = " + NL.toFixed(1) + " N, N_B = " + NR.toFixed(1) + " N, total " + (NL + NR).toFixed(1) + " N";

var g = 9.8, m = 12, L = 5.0;
var muReq = 0.5 / Math.tan(p.angle * Math.PI / 180);
var safe = p.mu >= muReq;

// if it cannot hold, let it slip: the foot slides out on a 2 s loop
var phi = p.angle * Math.PI / 180;
if (!safe) {
  var frac = (t % 2.0) / 2.0;
  var drop = Math.min(p.angle - 8, 26) * frac;
  phi = (p.angle - drop) * Math.PI / 180;
}

var wallX = W * 0.22, floorY = H * 0.84;
var scale = Math.min((W * 0.62) / (L * Math.cos(Math.max(phi, 0.2))), (floorY - H * 0.10) / (L * Math.sin(phi)));
var topY = floorY - L * scale * Math.sin(phi);
var footX = wallX + L * scale * Math.cos(phi);

ctx.font = "12px ui-sans-serif, system-ui, sans-serif";

// wall and floor
ctx.fillStyle = C.faint;
ctx.fillRect(wallX - 10, H * 0.06, 10, floorY - H * 0.06);
ctx.fillRect(wallX - 10, floorY, W - wallX - 4, 10);
ctx.fillStyle = C.ink;
ctx.fillText("frictionless wall", wallX + 6, H * 0.12);
ctx.fillText("rough floor, mu = " + p.mu.toFixed(2), W * 0.55, floorY + 26);

function arrow(sx, sy, ex, ey, col, lab) {
  var dx = ex - sx, dy = ey - sy, mm = Math.sqrt(dx * dx + dy * dy);
  var ux = dx / mm, uy = dy / mm;
  ctx.strokeStyle = col; ctx.fillStyle = col; ctx.lineWidth = 2.5;
  ctx.beginPath(); ctx.moveTo(sx, sy); ctx.lineTo(ex, ey); ctx.stroke();
  ctx.beginPath();
  ctx.moveTo(ex, ey);
  ctx.lineTo(ex - ux * 10 - uy * 5, ey - uy * 10 + ux * 5);
  ctx.lineTo(ex - ux * 10 + uy * 5, ey - uy * 10 - ux * 5);
  ctx.closePath(); ctx.fill();
  ctx.fillText(lab, ex + 4 * ux + 6, ey + 4 * uy - 4);
}

// ladder
ctx.strokeStyle = C.ink; ctx.lineWidth = 5;
ctx.beginPath(); ctx.moveTo(wallX, topY); ctx.lineTo(footX, floorY); ctx.stroke();

// centre of mass dot
var cmx = (wallX + footX) / 2, cmy = (topY + floorY) / 2;
ctx.fillStyle = C.ink;
ctx.beginPath(); ctx.arc(cmx, cmy, 5, 0, Math.PI * 2); ctx.fill();

var Nf = m * g;
var Nw = 0.5 * m * g / Math.tan(phi);
var fs = Nw;
var fsc = (W * 0.22) / (m * g);

arrow(wallX, topY, wallX + Nw * fsc, topY, C.accent, "N_wall");
arrow(footX, floorY, footX, floorY - Nf * fsc, C.accent, "N_floor");
arrow(footX, floorY, footX - fs * fsc, floorY, C.figure, "friction");
arrow(cmx, cmy, cmx, cmy + Nf * fsc, C.figure, "W = mg");

// angle arc at the foot
ctx.strokeStyle = C.rule; ctx.lineWidth = 1.5;
ctx.beginPath(); ctx.arc(footX, floorY, 30, Math.PI - phi, Math.PI); ctx.stroke();
ctx.fillStyle = C.ink;
ctx.fillText((phi * 180 / Math.PI).toFixed(0) + " deg", footX - 62, floorY - 10);

out.note = "friction needed: mu = 0.5/tan(angle) = " + muReq.toFixed(3) + "   floor supplies " + p.mu.toFixed(2) + (safe ? "   -> it holds" : "   -> it slips");

var V = 6.0, Rg = p.rg;
var R1 = p.r1, R2 = p.r2, R3 = p.r3, R4 = p.r4;

// node equations for VA, VB with P at 6 V and Q at 0 V
var a11 = 1/R1 + 1/R2 + 1/Rg, a12 = -1/Rg, b1 = V/R1;
var a22 = 1/R3 + 1/R4 + 1/Rg, a21 = -1/Rg, b2 = V/R3;
var det = a11*a22 - a12*a21;
var VA = (b1*a22 - a12*b2) / det;
var VB = (a11*b2 - b1*a21) / det;
var Ig = (VA - VB) / Rg;
var Itot = (V - VA)/R1 + (V - VB)/R3;
var Rpq = V / Itot;

var cx = W/2, cy = H/2;
var rx = Math.min(W*0.34, 190), ry = Math.min(H*0.30, 78);
var P = [cx - rx, cy], Q = [cx + rx, cy];
var A = [cx, cy - ry], B = [cx, cy + ry];

ctx.font = "12px ui-sans-serif, system-ui, sans-serif";
ctx.lineWidth = 1.6;
ctx.textAlign = "center";
ctx.textBaseline = "middle";

function wire(u, v, col) {
  ctx.strokeStyle = col;
  ctx.beginPath(); ctx.moveTo(u[0], u[1]); ctx.lineTo(v[0], v[1]); ctx.stroke();
}
function box(u, v, label, col) {
  var mx = (u[0]+v[0])/2, my = (u[1]+v[1])/2;
  var dx = v[0]-u[0], dy = v[1]-u[1];
  var L = Math.sqrt(dx*dx + dy*dy); dx /= L; dy /= L;
  var w = 20, h = 9;
  ctx.save();
  ctx.translate(mx, my);
  ctx.rotate(Math.atan2(dy, dx));
  ctx.fillStyle = C.paper;
  ctx.fillRect(-w, -h, 2*w, 2*h);
  ctx.strokeStyle = col;
  ctx.strokeRect(-w, -h, 2*w, 2*h);
  ctx.restore();
  ctx.fillStyle = C.ink;
  ctx.fillText(label, mx - dy*22, my + dx*22);
}
function node(u, name, volts) {
  ctx.fillStyle = C.accent;
  ctx.beginPath(); ctx.arc(u[0], u[1], 4, 0, Math.PI*2); ctx.fill();
  ctx.fillStyle = C.ink;
  ctx.fillText(name + "  " + volts, u[0], u[1] - 16);
}

wire(P, A, C.rule); wire(A, Q, C.rule);
wire(P, B, C.rule); wire(B, Q, C.rule);
wire(A, B, C.figure);

box(P, A, R1.toFixed(0) + " Ω", C.rule);
box(A, Q, R2.toFixed(0) + " Ω", C.rule);
box(P, B, R3.toFixed(0) + " Ω", C.rule);
box(B, Q, R4.toFixed(0) + " Ω", C.rule);
box(A, B, Rg.toFixed(0) + " Ω", C.figure);

ctx.fillStyle = C.ink;
ctx.fillText("P  6.00 V", P[0] - 4, P[1] - 16);
ctx.fillText("Q  0.00 V", Q[0] + 4, Q[1] - 16);
ctx.fillStyle = C.accent;
ctx.beginPath(); ctx.arc(P[0], P[1], 4, 0, Math.PI*2); ctx.fill();
ctx.beginPath(); ctx.arc(Q[0], Q[1], 4, 0, Math.PI*2); ctx.fill();
node(A, "A", VA.toFixed(3) + " V");
ctx.fillStyle = C.ink;
ctx.fillText("B  " + VB.toFixed(3) + " V", B[0], B[1] + 18);
ctx.fillStyle = C.accent;
ctx.beginPath(); ctx.arc(B[0], B[1], 4, 0, Math.PI*2); ctx.fill();

// animated charge in the bridge arm, speed set by the galvanometer current
var speed = Math.min(1.2, Math.abs(Ig) * 260);
var dir = Ig >= 0 ? 1 : -1;
if (speed > 0.004) {
  for (var k = 0; k < 4; k++) {
    var f = ((t * speed + k/4) % 1);
    var yy = A[1] + dir * f * (B[1] - A[1]);
    if (dir < 0) yy = B[1] + f * (A[1] - B[1]);
    ctx.fillStyle = C.figure;
    ctx.beginPath(); ctx.arc(A[0], yy, 3, 0, Math.PI*2); ctx.fill();
  }
} else {
  ctx.fillStyle = C.figure;
  ctx.fillText("balanced: no current", A[0] + 96, cy);
}

ctx.fillStyle = C.faint;
ctx.textAlign = "left";
ctx.fillText("ratio PA/AQ = " + (R1/R2).toFixed(3), 8, H - 26);
ctx.fillText("ratio PB/BQ = " + (R3/R4).toFixed(3), 8, H - 10);

out.note = "V(A) - V(B) = " + (VA - VB).toFixed(4) + " V, bridge current = "
  + (Ig*1000).toFixed(3) + " mA, R(P to Q) = " + Rpq.toFixed(2) + " Ω";

ctx.font = "12px ui-sans-serif, system-ui, sans-serif";
ctx.textAlign = "center";
ctx.textBaseline = "middle";

var s = Math.min((W - 150) / 1.45, (H - 60) / 1.35);
var ox = 46, oy = H - 26;
function X(v) { return ox + (v[0] + 0.45 * v[2]) * s; }
function Y(v) { return oy - (v[1] + 0.35 * v[2]) * s; }

var V = [];
for (var x = 0; x < 2; x++) for (var y = 0; y < 2; y++) for (var z = 0; z < 2; z++) V.push([x,y,z]);
function key(v) { return v[0] + "" + v[1] + "" + v[2]; }

var A = [0,0,0], G = [1,1,1];
function dist(u, v) { return Math.abs(u[0]-v[0]) + Math.abs(u[1]-v[1]) + Math.abs(u[2]-v[2]); }

// edges
for (var i = 0; i < V.length; i++) for (var j = i+1; j < V.length; j++) {
  if (dist(V[i], V[j]) !== 1) continue;
  var dA = Math.min(dist(V[i], A), dist(V[j], A));
  var dB = Math.min(dist(V[i], G), dist(V[j], G));
  var near = (dA === 0) || (dB === 0);
  ctx.strokeStyle = near ? C.accent : C.rule;
  ctx.lineWidth = near ? 2 : 1.4;
  ctx.beginPath(); ctx.moveTo(X(V[i]), Y(V[i])); ctx.lineTo(X(V[j]), Y(V[j])); ctx.stroke();
}

// vertices, coloured by distance from A
for (var i2 = 0; i2 < V.length; i2++) {
  var v = V[i2], d = dist(v, A);
  ctx.fillStyle = (d === 0 || d === 3) ? C.accent : C.figure;
  ctx.beginPath(); ctx.arc(X(v), Y(v), (d === 0 || d === 3) ? 6 : 5, 0, Math.PI*2); ctx.fill();
  ctx.fillStyle = C.ink;
  var lab = d === 0 ? "A" : (d === 3 ? "G" : (d === 1 ? "1" : "2"));
  ctx.fillText(lab, X(v) + 12, Y(v) - 11);
}

ctx.lineWidth = 1;
ctx.textAlign = "left";
ctx.fillStyle = C.ink;
var tx = W - 132;
ctx.fillText("A to tier 1:  R/3", tx, 24);
ctx.fillText("tier 1 to 2:  R/6", tx, 44);
ctx.fillText("tier 2 to G:  R/3", tx, 64);
ctx.strokeStyle = C.rule;
ctx.beginPath(); ctx.moveTo(tx, 76); ctx.lineTo(tx + 116, 76); ctx.stroke();
ctx.fillStyle = C.accent;
ctx.fillText("total  =  5R/6", tx, 92);
ctx.fillStyle = C.faint;
ctx.fillText("the three 1s share a potential,", tx, 118);
ctx.fillText("and so do the three 2s", tx, 134);

out.note = "Every corner marked 1 is one step from A; every corner marked 2 is two steps. Corners with the same label sit at the same potential.";

var Rs = p.rs, Rp = p.rp, n = Math.round(p.n);

// exact infinite-ladder value: X is the resistance looking in at a shunt node
var Xinf = (-Rp + Math.sqrt(Rp*Rp + 4*Rp*Rs)) / 2;
var Rinf = Rs + Xinf;

// finite ladder with n sections, built from the far end backwards
var X = Rp;
for (var k = 1; k < n; k++) { X = 1 / (1/Rp + 1/(Rs + X)); }
