ctx.fillStyle = C.rule;
ctx.fillText("stops at " + dStop.toFixed(2) + " m", stx + 6, sty - 10);

var px = bx0 + s * mScale * Math.cos(th), py = by0 - s * mScale * Math.sin(th);
var bs = Math.max(H * 0.09, 12);
ctx.save();
ctx.translate(px, py);
ctx.rotate(-th);
ctx.strokeStyle = C.accent; ctx.lineWidth = 2;
ctx.strokeRect(-bs / 2, -bs, bs, bs);
ctx.restore();

var K = 0.5 * m * v * v;
ctx.fillStyle = C.figure;
ctx.fillText("v = " + Math.abs(v).toFixed(2) + " m/s", W * 0.55, H * 0.20);
ctx.fillText("K = " + K.toFixed(1) + " J", W * 0.55, H * 0.20 + 16);
ctx.fillStyle = C.faint;
ctx.fillText("m = 2.0 kg", W * 0.55, H * 0.20 + 32);

out.note = "gravity takes " + (m * g * Math.sin(th) * dStop).toFixed(1) + " J, friction takes " + (mu * m * g * Math.cos(th) * dStop).toFixed(1) + " J, start K = " + (0.5 * m * v0 * v0).toFixed(1) + " J, stopping distance " + dStop.toFixed(2) + " m";
